-- La migración `equipo` (work/equipo/SPEC.md §4, §5.3 y §12). No la escribió
-- `migrate dev` entera: el esquema es el que da `prisma migrate diff
-- --from-config-datasource --to-schema`, partido para mover los datos antes
-- del DROP de `autorias.persona` (como la de la 8a, que `migrate dev` no
-- corre sin terminal cuando borra una columna con datos), y el resto se sumó
-- antes de la primera aplicación (ADR-0011).

-- CreateTable
CREATE TABLE "equipo" (
    "id" TEXT NOT NULL,
    "slug" TEXT,
    "nombre" TEXT,
    "rol" TEXT,
    "pais" TEXT,
    "nivel" SMALLINT,
    "foto" JSONB,
    "sin_foto" BOOLEAN NOT NULL DEFAULT false,
    "acercamiento" DOUBLE PRECISION NOT NULL DEFAULT 1,
    "orden" INTEGER NOT NULL DEFAULT 0,
    "nombre_completo" TEXT,
    "rol_completo" TEXT,
    "lugar" TEXT,
    "origen" TEXT,
    "titular" TEXT,
    "intro" TEXT,
    "formacion" JSONB,
    "categorias" JSONB,
    "figura" JSONB,
    "etapas" JSONB,
    "cierre_titulo" TEXT,
    "cierre_texto" TEXT,
    "cierre_texto_2" TEXT,
    "publicado" BOOLEAN NOT NULL DEFAULT false,
    "publicado_en" TIMESTAMP(3),
    "publicado_por" TEXT,
    "borrador" JSONB,
    "borrador_en" TIMESTAMP(3),
    "borrador_por" TEXT,
    "creado_en" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "creado_por" TEXT,

    CONSTRAINT "equipo_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE UNIQUE INDEX "equipo_slug_key" ON "equipo"("slug");

-- La Dirección general es una sola: el masthead tiene un lugar al centro
-- (SPEC §4.1). Prisma no escribe índices parciales sin un preview feature, así
-- que va a mano, como `novedades_una_sola_destacada`; `migrate diff` no lo ve
-- como drift. Frena también dos publicaciones a la vez, que un chequeo previo
-- no ve.
CREATE UNIQUE INDEX "equipo_una_sola_direccion_general" ON "equipo" ("nivel") WHERE "nivel" = 1 AND "publicado";

-- Los 15 perfiles de hoy (SPEC §3 y §4), para que producción los tenga en el
-- primer deploy: el SQL lo generó un script desde
-- `features/quienes-somos/data/equipo.ts`, validando cada fila con
-- `esquemaPersona`, y ese archivo se borra con la lane. Entran publicados y
-- sin `publicado_por`: los cargó la migración, no una persona. La clave de
-- hoy pasa a ser el slug; los ids son fijos, así cada base tiene los mismos.
-- `orden`, el lugar de cada persona dentro de su nivel en el archivo.
-- - La foto de la tarjeta: `/equipo/<clave>.jpg`, con el nombre de alt (el de
--   hoy) y el foco que sale de `imagePosition`; el acercamiento, `imageZoom`.
-- - El recorrido: una columna por texto; las categorías, la figura (la misma
--   foto, con el nombre completo de alt y su foco) y las etapas, en `jsonb`.
--   `cutoutSize` no se muda (SPEC §4.1): con la figura en marco no se usa.
-- - Las 78 publicaciones de las etapas: 64 pasan a referencias a su material
--   (las 59 que ya estaban en la Biblioteca y las 5 que entran abajo), con el
--   detalle vacío en las 7 que decían exactamente la fuente, y el destacado de
--   Daniela Reyes con «Editorial Gedisa» (SPEC §8.2); las 14 sin link quedan
--   escritas en su etapa, con su tipo de la Biblioteca (SPEC §5.3).
-- - `bio`, `linkedin` y `pubs` no se mudan: nada del sitio los lee (SPEC §4.3).
INSERT INTO "equipo" ("id", "slug", "nombre", "rol", "pais", "nivel", "foto", "sin_foto", "acercamiento", "orden", "nombre_completo", "rol_completo", "lugar", "origen", "titular", "intro", "formacion", "categorias", "figura", "etapas", "cierre_titulo", "cierre_texto", "cierre_texto_2", "publicado", "publicado_en") VALUES
  ('66f2382e-31e8-494f-910c-4d1bfe962dc3', 'daniela-reyes', 'Daniela Reyes', 'Directora General', 'Argentina', 1, '{"src":"/equipo/daniela-reyes.jpg","alt":"Daniela Reyes","foco":{"x":0.5,"y":0.2}}', false, 1, 0, 'Daniela Reyes-Gasperini', 'Dirección General', 'Santiago de Chile, Chile', 'Buenos Aires, Argentina', 'Del aula a la investigación. De la investigación, a la transformación educativa.', 'Profesora de Matemática, investigadora y asesora educativa. Su recorrido conecta la práctica docente, la Matemática Educativa, el diseño curricular y las políticas de transformación.', '["Profesora de Matemática","Magíster en Ciencias — Matemática Educativa","Doctora en Ciencias — Matemática Educativa","Especialista en Política y Gestión Educativa"]', '[{"clave":"matematica-educativa","etiqueta":"Matemática educativa","color":"azul"},{"clave":"empoderamiento-docente","etiqueta":"Empoderamiento docente","color":"verde"},{"clave":"investigacion-aplicada","etiqueta":"Investigación aplicada","color":"azul"},{"clave":"desarrollo-profesional","etiqueta":"Desarrollo profesional docente","color":"verde"},{"clave":"politica-transformacion","etiqueta":"Política y transformación educativa","color":"naranja"}]', '{"tipo":"marco","foto":{"src":"/equipo/daniela-reyes.jpg","alt":"Daniela Reyes-Gasperini","foco":{"x":0.5,"y":0.22}},"apaisado":false}', '[{"clave":"aula","categoria":"matematica-educativa","volanta":"El aula como origen","color":"verde","periodo":"2008 – 2009","composicion":"editorial","titulo":"Todo comenzó enseñando Matemática.","texto":"Daniela comenzó su recorrido como profesora de Matemática en escuelas secundarias de Buenos Aires. La práctica docente fue el punto de partida de una pregunta que atravesaría toda su trayectoria: cómo transformar la relación entre el profesorado, el saber matemático y el aula.","cita":"","hitos":[{"periodo":"","titulo":"Colegio Francesco Faà di Bruno","detalle":"Profesora de Matemática — Buenos Aires","principal":false},{"periodo":"","titulo":"Instituto William C. Morris","detalle":"Profesora de Matemática — Buenos Aires","principal":false},{"periodo":"","titulo":"Instituto Superior del Profesorado «Dr. Joaquín V. González»","detalle":"Formación y docencia — Buenos Aires","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]},{"clave":"mexico","categoria":"investigacion-aplicada","volanta":"Investigar la práctica","color":"azul","periodo":"2009 – 2016","composicion":"ficha","titulo":"Del aula a la Matemática Educativa.","texto":"En México, su experiencia docente se convirtió en investigación. Cursó la maestría y el doctorado en Matemática Educativa en el Cinvestav-IPN, profundizando en la socioepistemología y en los procesos de transformación de la práctica docente.","cita":"","hitos":[{"periodo":"2009 – 2011","titulo":"Maestría en Ciencias — Matemática Educativa","detalle":"Cinvestav-IPN, México","principal":false},{"periodo":"2012 – 2016","titulo":"Doctorado en Ciencias — Matemática Educativa","detalle":"Cinvestav-IPN, México","principal":false}],"ramas":[{"periodo":"2015","lugar":"Francia","detalle":"Estancia doctoral — Université Paris Diderot · Paris 7"},{"periodo":"2015","lugar":"Portugal","detalle":"Estancia doctoral — Instituto de Educação, Universidad de Lisboa"}],"territorios":[],"publicaciones":[]},{"clave":"empoderamiento","categoria":"empoderamiento-docente","volanta":"Una idea toma forma","color":"verde","periodo":"2011 – 2016","composicion":"concepto","titulo":"Empoderamiento docente desde la socioepistemología.","texto":"Durante su maestría y doctorado desarrolló una línea de investigación centrada en el empoderamiento docente: no como poder sobre otras personas, sino como la construcción de saber, convicción y herramientas para transformar la práctica educativa.","cita":"Empoderamiento docente desde una visión Socioepistemológica: una alternativa de intervención para el cambio y la mejora educativa.","hitos":[{"periodo":"2011","titulo":"Tesis de maestría","detalle":"«Empoderamiento docente desde una visión Socioepistemológica: estudio de los factores de cambio en las prácticas del profesor de matemáticas.»","principal":false},{"periodo":"2013","titulo":"Memoria predoctoral","detalle":"«Empoderamiento docente desde una visión Socioepistemológica: una alternativa de intervención para el cambio y la mejora educativa.»","principal":false},{"periodo":"2016","titulo":"Tesis doctoral","detalle":"«Empoderamiento docente desde una visión Socioepistemológica: una alternativa de intervención para el cambio y la mejora educativa.»","principal":false}],"ramas":[],"territorios":[],"publicaciones":[{"origen":"biblioteca","material":"c9144f58-8df0-4bfb-bd00-370457842df6","detalle":"Editorial Gedisa","conceptos":[],"destacada":true}]},{"clave":"formacion","categoria":"desarrollo-profesional","volanta":"De la investigación a la acción","color":"naranja","periodo":"2012 – 2020","composicion":"hitos","titulo":"La investigación se convirtió en trabajo institucional.","texto":"Su trabajo se expandió hacia la formación de docentes, el diseño curricular, la innovación educativa y la construcción de políticas públicas en Matemáticas.","cita":"","hitos":[{"periodo":"2014 – 2017","titulo":"Diseño del currículo de Matemáticas — Educación Media Superior","detalle":"México","principal":true},{"periodo":"2018","titulo":"Dirección Académica e Innovación Educativa","detalle":"Secretaría de Educación Pública de México","principal":true},{"periodo":"2012 – 2014","titulo":"Docencia de posgrado para formación docente","detalle":"Oaxaca, México","principal":false},{"periodo":"2016 – 2018","titulo":"Coordinación académica — Desarrollo Profesional Docente en Matemáticas","detalle":"Programa Interdisciplinario, Cinvestav-IPN","principal":false},{"periodo":"2017 – 2018","titulo":"Dirección de área y asesoría académica","detalle":"Construye T","principal":false},{"periodo":"2020 – 2023","titulo":"Consejo Técnico de los Exámenes Nacionales de Ingreso","detalle":"CENEVAL","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]},{"clave":"internacional","categoria":"politica-transformacion","volanta":"Una mirada que cruza contextos","color":"azul","periodo":"","composicion":"mapa","titulo":"Argentina, México y Chile: una trayectoria regional.","texto":"Su recorrido se construyó entre aulas, universidades, ministerios, organizaciones y equipos de distintos países. Esa experiencia regional permitió conectar investigación, práctica docente y transformación institucional.","cita":"","hitos":[],"ramas":[],"territorios":["Argentina","México","Chile","Estancias en Francia y Portugal","Publicación internacional · UNESCO y educación inclusiva"],"publicaciones":[]},{"clave":"produccion","categoria":"investigacion-aplicada","volanta":"Investigación, libros y materiales","color":"azul","periodo":"","composicion":"ramas","titulo":"Investigar para construir herramientas.","texto":"Su producción articula investigación, formación docente y materiales destinados a transformar la enseñanza de la Matemática.","cita":"","hitos":[],"ramas":[],"territorios":[],"publicaciones":[{"origen":"sin-link","titulo":"La transversalidad de la proporcionalidad","tipo":"Libros","anio":"2013","detalle":"Secretaría de Educación Pública de México","conceptos":[],"destacada":false},{"origen":"biblioteca","material":"cf6c2e66-f0f6-4758-9cbe-b54987a6f2a9","detalle":"Con Ricardo Cantoral · Bolema","conceptos":[],"destacada":false},{"origen":"biblioteca","material":"c9144f58-8df0-4bfb-bd00-370457842df6","detalle":"Editorial Gedisa","conceptos":[],"destacada":true},{"origen":"biblioteca","material":"c62342e8-7d0a-471f-bdaf-5dc3273de184","detalle":"Nota de divulgación · Roberto Rocca, Grupo Techint","conceptos":[],"destacada":false},{"origen":"biblioteca","material":"8577d001-b5e0-4539-9fed-8f39d65e905c","detalle":"Con Karla Gómez-Osalde · Propuesta Educativa","conceptos":[],"destacada":false},{"origen":"biblioteca","material":"eb3d26fa-92b8-447b-85b7-77622b39f335","detalle":"Coordinación de publicaciones · Ministerio de Educación de la Ciudad de Buenos Aires","conceptos":[],"destacada":false},{"origen":"biblioteca","material":"a56bfdd2-140c-44e8-9de8-247f1afba808","detalle":"","conceptos":[],"destacada":false},{"origen":"biblioteca","material":"77e32742-f657-4908-8491-ea501f0b05f0","detalle":"Colección de materiales para el desarrollo del pensamiento matemático","conceptos":["Inferir","Medir","Aproximar","Comparar","Equivaler","Predecir","Visualizar"],"destacada":false}]},{"clave":"convergencia","categoria":"empoderamiento-docente","volanta":"La convergencia","color":"verde","periodo":"2020 – actualidad","composicion":"sintesis","titulo":"Una trayectoria que converge en ED.","texto":"Empoderamiento Docente reúne los distintos planos de su recorrido: aula, investigación, formación docente, diseño curricular, materiales, políticas educativas y liderazgo institucional.","cita":"","hitos":[{"periodo":"2020 – actualidad","titulo":"Directora General de Empoderamiento Docente","detalle":"","principal":true},{"periodo":"2020 – actualidad","titulo":"Fundadora de Casa Bosque – Escuela Montessori","detalle":"Chile","principal":false},{"periodo":"2021 – actualidad","titulo":"Asesora global en Matemáticas","detalle":"Techint Group","principal":false},{"periodo":"2022 – 2024","titulo":"Profesora del Diplomado en Matemática Educativa","detalle":"UDLA Chile","principal":false},{"periodo":"2023","titulo":"Profesora honoraria de Didáctica de la Matemática","detalle":"UMCE","principal":false},{"periodo":"2023 – actualidad","titulo":"Asesora ministerial en Matemáticas","detalle":"Plan Estratégico Buenos Aires Aprende","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]}]', 'Del recorrido individual a una construcción colectiva.', 'Desde la Dirección General, Daniela articula investigación, asesoría, formación docente, diseño de materiales y construcción de equipos para transformar contextos educativos concretos.', 'ED es el punto donde su trayectoria entre aula, saber, política educativa y transformación se convierte en acción colectiva.', true, CURRENT_TIMESTAMP),
  ('fa0f5308-40a2-47be-a191-5638e7317c1d', 'karla-gomez', 'Karla Gómez', 'Directora Académica', 'México', 2, '{"src":"/equipo/karla-gomez.jpg","alt":"Karla Gómez","foco":{"x":0.5,"y":0.16}}', false, 1, 0, 'Karla Gómez Osalde', 'Dirección Académica', 'Chile', 'Mérida, Yucatán, México', 'Una tarea bien diseñada cambia la conversación del aula.', 'Profesora de matemáticas y doctora en Matemática Educativa. Trabaja sobre el desarrollo del pensamiento geométrico y el diseño de tareas que hacen hablar a la matemática escolar. Desde la Dirección Académica de ED tiene a su cargo los materiales que median el aprendizaje.', '["Licenciada en Enseñanza de las Matemáticas — UADY","Maestra en Ciencias — Matemática Educativa, Cinvestav-IPN","Doctora en Ciencias — Matemática Educativa, Cinvestav-IPN"]', '[{"clave":"pensamiento-geometrico","etiqueta":"Pensamiento geométrico","color":"verde"},{"clave":"diseno-tareas","etiqueta":"Diseño de tareas","color":"naranja"},{"clave":"desarrollo-profesional","etiqueta":"Desarrollo profesional docente","color":"verde"},{"clave":"investigacion","etiqueta":"Investigación en Matemática Educativa","color":"azul"}]', '{"tipo":"marco","foto":{"src":"/equipo/karla-gomez.jpg","alt":"Karla Gómez Osalde","foco":{"x":0.5,"y":0.16}},"apaisado":false}', '[{"clave":"formacion","categoria":"investigacion","volanta":"De Yucatán al Cinvestav","color":"azul","periodo":"2007 – 2015","composicion":"ficha","titulo":"Ocho años de formación seguidos.","texto":"Se recibió de Licenciada en Enseñanza de las Matemáticas en la Universidad Autónoma de Yucatán y siguió, sin pausa, con la maestría y el doctorado en Matemática Educativa en el Cinvestav-IPN.","cita":"","hitos":[{"periodo":"2007","titulo":"Licenciatura en Enseñanza de las Matemáticas","detalle":"Universidad Autónoma de Yucatán","principal":false},{"periodo":"2009","titulo":"Maestría en Ciencias — Matemática Educativa","detalle":"Cinvestav-IPN","principal":false},{"periodo":"2015","titulo":"Doctorado en Ciencias — Matemática Educativa","detalle":"Cinvestav-IPN","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]},{"clave":"uady","categoria":"desarrollo-profesional","volanta":"Profesora de carrera","color":"verde","periodo":"2015 – 2021","composicion":"hitos","titulo":"Seis años en la Facultad de Matemáticas.","texto":"Fue Profesora de Carrera en Educación Superior en la UADY: docencia en didáctica de las matemáticas, dirección de tesis y trabajo dentro del cuerpo académico.","cita":"","hitos":[{"periodo":"2015 – 2021","titulo":"Profesora de Carrera en Educación Superior","detalle":"Facultad de Matemáticas, Universidad Autónoma de Yucatán","principal":true},{"periodo":"","titulo":"Integrante del Cuerpo Académico Enseñanza de las Matemáticas","detalle":"","principal":false},{"periodo":"","titulo":"Miembro del grupo formulador del plan de estudios de la maestría en Docencia Matemática","detalle":"","principal":false},{"periodo":"","titulo":"Dirección de proyectos de tesis a nivel licenciatura","detalle":"","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]},{"clave":"talleres","categoria":"desarrollo-profesional","volanta":"Del aula universitaria a la escuela","color":"naranja","periodo":"2018","composicion":"editorial","titulo":"Talleres en los municipios de Yucatán.","texto":"Coordinó el diseño y la implementación de los talleres de didáctica de las matemáticas para clubes de primaria alta y secundaria, en convenio con la Secretaría de Educación del estado, y acompañó a docentes en la puesta en marcha de los materiales.","cita":"","hitos":[{"periodo":"2018","titulo":"Coordinación de diseño e implementación de talleres didácticos en educación básica","detalle":"Facultad de Matemáticas UADY, con la Secretaría de Educación de Yucatán","principal":false},{"periodo":"","titulo":"Acompañamiento a docentes del estado en la implementación de materiales","detalle":"","principal":false},{"periodo":"","titulo":"Capacitación y asesoría al equipo de instructores","detalle":"","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]},{"clave":"geometria","categoria":"pensamiento-geometrico","volanta":"La línea de trabajo","color":"azul","periodo":"","composicion":"ramas","titulo":"Reconceptualizar la geometría escolar.","texto":"Su investigación estudia el desarrollo del pensamiento geométrico y el diseño de tareas que promuevan la comunicación de la matemática escolar: no la geometría como catálogo de figuras, sino como algo que se construye conversando.","cita":"","hitos":[],"ramas":[],"territorios":[],"publicaciones":[{"origen":"biblioteca","material":"c189d22b-472c-47e4-9fd1-c109cf64a529","detalle":"Revista Latinoamericana de Investigación en Matemática Educativa","conceptos":[],"destacada":true},{"origen":"biblioteca","material":"8577d001-b5e0-4539-9fed-8f39d65e905c","detalle":"Con Daniela Reyes-Gasperini · Propuesta Educativa","conceptos":[],"destacada":false},{"origen":"biblioteca","material":"4ea0b4a5-6468-4630-b5d5-7fdf2f6704de","detalle":"","conceptos":[],"destacada":false},{"origen":"biblioteca","material":"59e331f3-d253-4038-9426-da28217360e6","detalle":"Con Eddie Aparicio y Landy Sosa · Memorias del PME-NA 42","conceptos":[],"destacada":false},{"origen":"biblioteca","material":"071d4634-8c1b-4423-81be-51561480638d","detalle":"Capítulo, con Landy Sosa — Prospecção de Problemas e Soluções nas Ciências Matemáticas 3 · Atena Editora","conceptos":[],"destacada":false},{"origen":"biblioteca","material":"e677f12b-4a52-4562-91c0-9e3d6847476a","detalle":"Capítulo — Educación Matemática en las Américas 2019 · CIAEM","conceptos":[],"destacada":false},{"origen":"biblioteca","material":"07ae0b6b-a6a5-49c4-8a63-6ecc68c6137a","detalle":"","conceptos":[],"destacada":false},{"origen":"biblioteca","material":"8de04245-2304-4677-9553-843773e5496b","detalle":"Universidad Autónoma de Yucatán","conceptos":[],"destacada":false}]},{"clave":"convergencia","categoria":"diseno-tareas","volanta":"La convergencia","color":"verde","periodo":"actualidad","composicion":"sintesis","titulo":"Dirección Académica en ED.","texto":"Desde Chile dirige el trabajo académico de Empoderamiento Docente: el diseño de ambientes de desarrollo profesional en Matemáticas y de los materiales que median el aprendizaje.","cita":"","hitos":[{"periodo":"","titulo":"Directora Académica — Empoderamiento Docente","detalle":"","principal":true},{"periodo":"","titulo":"Diseño de materiales mediadores del aprendizaje","detalle":"","principal":false},{"periodo":"","titulo":"Programas de desarrollo profesional en Latinoamérica","detalle":"","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]}]', 'Del pensamiento geométrico al material que llega al aula.', 'Investigación sobre cómo se construye el pensamiento geométrico, seis años formando profesorado en la universidad y talleres en escuelas de todo un estado.', 'En ED, ese recorrido decide qué tarea se pone sobre la mesa.', true, CURRENT_TIMESTAMP),
  ('62619fae-7ffc-4516-8b33-a46740fda579', 'raquel-ayala', 'Raquel Ayala', 'Gestión institucional', 'Argentina', 2, '{"src":"/equipo/raquel-ayala.jpg","alt":"Raquel Ayala","foco":{"x":0.5,"y":0.5}}', false, 1, 1, 'Raquel Ayala', 'Gestión institucional', 'Buenos Aires, Argentina', NULL, 'De administrar personas a sostener una organización educativa.', 'Licenciada en Psicología, perita grafóloga superior y diplomada en Estudios de Género. Antes de ED trabajó más de una década en administración —forestal, de personal y logística—, se formó en clínica dentro del sistema público de salud y fue socia de una consultora de recursos humanos.', '["Licenciada en Psicología — Universidad de Buenos Aires","Perita Grafóloga Superior — ICEA Altos Estudios","Diplomada en Estudios de Género — Universidad Tecnológica Nacional","Concurrencia en Psicología Clínica — GCBA"]', '[{"clave":"gestion-institucional","etiqueta":"Gestión institucional","color":"azul"},{"clave":"equipos-y-personas","etiqueta":"Equipos y personas","color":"azul"},{"clave":"psicologia","etiqueta":"Psicología","color":"verde"},{"clave":"genero-y-cuidados","etiqueta":"Género y cuidados","color":"naranja"}]', '{"tipo":"marco","foto":{"src":"/equipo/raquel-ayala.jpg","alt":"Raquel Ayala","foco":{"x":0.5,"y":0.5}},"apaisado":false}', '[{"clave":"administracion","categoria":"equipos-y-personas","volanta":"El punto de partida","color":"azul","periodo":"2003 – 2015","composicion":"hitos","titulo":"Administrar es ordenar lo que sostiene a una organización.","texto":"Su recorrido laboral empezó lejos del aula y cerca de lo que hace que una organización funcione: administración forestal primero, administración de personal y logística después.","cita":"","hitos":[{"periodo":"2003 – 2010","titulo":"Papel Prensa S.A.","detalle":"Administración forestal","principal":true},{"periodo":"2010 – 2012","titulo":"Oil Quality S.A.","detalle":"Administración de personal","principal":false},{"periodo":"2013 – 2015","titulo":"Establecimientos Caporaso","detalle":"Administración de personal y logística","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]},{"clave":"psicologia","categoria":"psicologia","volanta":"Una formación en paralelo","color":"verde","periodo":"2005 – 2013","composicion":"ficha","titulo":"La psicología, cursada mientras trabajaba.","texto":"En paralelo al trabajo administrativo se formó como perita grafóloga y se recibió de Licenciada en Psicología en la Universidad de Buenos Aires.","cita":"","hitos":[{"periodo":"2005 – 2007","titulo":"Perita Grafóloga Superior","detalle":"ICEA Altos Estudios","principal":false},{"periodo":"2006 – 2013","titulo":"Licenciatura en Psicología","detalle":"Universidad de Buenos Aires","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]},{"clave":"clinica","categoria":"psicologia","volanta":"El sistema público","color":"verde","periodo":"2015 – 2020","composicion":"editorial","titulo":"Cinco años de clínica en hospitales de la Ciudad.","texto":"Hizo la concurrencia en Psicología Clínica en el Hospital Pirovano y el CeSAC N° 2, dentro del sistema público de salud porteño. En esos años se formó en atención primaria, salud sexual y reproductiva y abordajes comunitarios.","cita":"","hitos":[{"periodo":"2015 – 2020","titulo":"Concurrencia en Psicología Clínica","detalle":"Hospital Pirovano y CeSAC N° 2 — GCBA","principal":false},{"periodo":"2016 – 2017","titulo":"Problemáticas actuales intra y extramuro en atención primaria","detalle":"Participante y docente — Hospital Pirovano","principal":false},{"periodo":"2017","titulo":"Jornadas «Devenir de la Atención Comunitaria»","detalle":"Secretaría administrativa del comité — Hospital Pirovano","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]},{"clave":"consultoria","categoria":"equipos-y-personas","volanta":"Del caso a la organización","color":"azul","periodo":"2016 – 2022","composicion":"hitos","titulo":"Consultoría en recursos humanos, como socia.","texto":"Durante seis años fue socia en NGA: la mirada psicológica puesta a trabajar sobre equipos y organizaciones enteras, no sobre casos individuales.","cita":"","hitos":[{"periodo":"2016 – 2022","titulo":"Socia en NGA","detalle":"Consultoría y asesoramiento integral en Recursos Humanos","principal":true}],"ramas":[],"territorios":[],"publicaciones":[]},{"clave":"genero","categoria":"genero-y-cuidados","volanta":"Una perspectiva que ordena el resto","color":"naranja","periodo":"2021 – 2023","composicion":"concepto","titulo":"Género, diversidad y cuidados como criterio de gestión.","texto":"Se formó en estudios de género y en gestión de igualdad, diversidad y cuidados. Es una perspectiva que atraviesa cómo se arman los equipos y cómo se sostienen los procesos, no un tema aparte.","cita":"","hitos":[{"periodo":"2021","titulo":"Formadora de evaluadores — Premio Nacional a la Calidad","detalle":"Gestión de igualdad de género, diversidad y cuidados","principal":false},{"periodo":"2022","titulo":"Diplomatura en Estudios de Género","detalle":"Universidad Tecnológica Nacional","principal":false},{"periodo":"2023","titulo":"ONU Mujeres","detalle":"Igualdad de género en empresas públicas · corresponsabilidad y cuidados · masculinidades","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]},{"clave":"guardia","categoria":"psicologia","volanta":"En ejercicio","color":"verde","periodo":"2023 – actualidad","composicion":"editorial","titulo":"La clínica sigue abierta.","texto":"Trabaja como psicóloga de guardia suplente en el Hospital General de Agudos Juan A. Fernández.","cita":"","hitos":[{"periodo":"2023 – actualidad","titulo":"Hospital Gral. de Agudos Juan A. Fernández","detalle":"Psicóloga de guardia suplente","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]},{"clave":"convergencia","categoria":"gestion-institucional","volanta":"La convergencia","color":"azul","periodo":"actualidad","composicion":"sintesis","titulo":"Gestión institucional en ED.","texto":"En Empoderamiento Docente está a cargo de la gestión institucional.","cita":"","hitos":[{"periodo":"","titulo":"Gestión institucional — Empoderamiento Docente","detalle":"Argentina","principal":true}],"ramas":[],"territorios":[],"publicaciones":[]}]', 'Un recorrido que llega a la gestión.', 'Administración, psicología clínica, consultoría de recursos humanos y perspectiva de género convergen en el trabajo de sostener una organización que trabaja en cinco países.', NULL, true, CURRENT_TIMESTAMP),
  ('96d48734-9535-4cf2-8d1f-5d442a90fd86', 'ivan-perez', 'Iván Pérez', 'Líder de Modelación y Tecnologías', 'Chile', 3, '{"src":"/equipo/ivan-perez.jpg","alt":"Iván Pérez","foco":{"x":0.5,"y":0.22}}', false, 1, 0, 'Iván Esteban Pérez Vera', 'Líder de Modelación y Tecnologías', 'Santiago, Chile', NULL, 'Modelar el mundo para entender la matemática.', 'Profesor de matemáticas y académico de la Universidad Metropolitana de Ciencias de la Educación, en Chile. Investiga la modelación matemática escolar y el uso de tecnologías en la enseñanza, y forma a quienes van a enseñar matemática.', '["Profesor de Matemáticas","Postítulo en Informática Educativa","Magíster en Educación Matemática","Candidato a Doctor en Educación"]', '[{"clave":"modelacion","etiqueta":"Modelación matemática escolar","color":"verde"},{"clave":"tecnologias","etiqueta":"Tecnologías e informática educativa","color":"azul"},{"clave":"formacion-inicial","etiqueta":"Formación inicial docente","color":"naranja"}]', '{"tipo":"marco","foto":{"src":"/equipo/ivan-perez.jpg","alt":"Iván Esteban Pérez Vera","foco":{"x":0.5,"y":0.22}},"apaisado":false}', '[{"clave":"aula","categoria":"formacion-inicial","volanta":"El aula como origen","color":"verde","periodo":"","composicion":"editorial","titulo":"Primero, enseñar matemáticas en la escuela.","texto":"Antes de la carrera académica trabajó en el sistema escolar chileno como profesor de matemáticas en todos los niveles de secundaria, en escuelas públicas y privadas. Esa experiencia definió lo que vino después: durante el posgrado decidió enfocarse en la formación inicial de profesores y en el uso de tecnologías para enseñar matemática.","cita":"","hitos":[{"periodo":"","titulo":"Profesor de matemáticas en secundaria","detalle":"Escuelas públicas y privadas de Chile","principal":false},{"periodo":"","titulo":"Postítulo en Informática Educativa","detalle":"","principal":false},{"periodo":"","titulo":"Magíster en Educación Matemática","detalle":"","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]},{"clave":"umce","categoria":"tecnologias","volanta":"Formar a quienes van a enseñar","color":"azul","periodo":"","composicion":"hitos","titulo":"Informática educativa en la formación de profesores.","texto":"En la Universidad Metropolitana de Ciencias de la Educación lidera la mención de Informática Educativa de la Licenciatura en Educación Matemática y dirige proyectos de vinculación con el medio escolar, investigación y tesis de licenciatura y magíster sobre tecnologías y modelación.","cita":"","hitos":[{"periodo":"","titulo":"Líder de la mención de Informática Educativa — Licenciatura en Educación Matemática","detalle":"Universidad Metropolitana de Ciencias de la Educación","principal":true},{"periodo":"","titulo":"Académico del Departamento de Matemática","detalle":"Responsable de proyectos de investigación y de vinculación con el medio escolar · UMCE","principal":false},{"periodo":"","titulo":"Dirección de tesis de licenciatura y magíster","detalle":"Tecnologías y modelación matemática","principal":false},{"periodo":"","titulo":"Candidato a Doctor en Educación","detalle":"","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]},{"clave":"modelacion","categoria":"modelacion","volanta":"Modelar para aprender","color":"verde","periodo":"2024 – 2026","composicion":"ramas","titulo":"La elipse, el plano inclinado, el consumo sostenible.","texto":"Su investigación reciente estudia la modelación matemática escolar en situaciones reales —una órbita, un plano inclinado, una colisión, la producción sostenible— y cómo se integra con las tecnologías, incluida la inteligencia artificial generativa, en la formación inicial docente. Buena parte la escribe con estudiantes y con profesoras y profesores en formación, y una línea mira los sesgos de género en las experiencias de modelación.","cita":"","hitos":[],"ramas":[],"territorios":[],"publicaciones":[{"origen":"biblioteca","material":"e2001c90-35a7-4020-a879-ca504c378ab9","detalle":"Con K. Pacheco-López · Revista Chilena de Educación Matemática","conceptos":[],"destacada":true},{"origen":"biblioteca","material":"77e33cff-b8a7-4e00-a434-520435e54a7d","detalle":"Con A. Espinoza-Salomón, R. Jorquera-Soto y T. Osorio-Gómez · Investigación e Innovación en Matemática Educativa","conceptos":[],"destacada":false},{"origen":"biblioteca","material":"ac49f77f-d035-4a6c-993f-a6bdfecb431a","detalle":"Con S. Giovanetti, S. Riquelme y R. Vilches · Cuadernos de Investigación y Formación en Educación Matemática","conceptos":[],"destacada":false},{"origen":"biblioteca","material":"36a39f24-e8ff-4e6c-8bdd-45aa296930d1","detalle":"Con P. Salazar-Cortez · El Cálculo y su Enseñanza","conceptos":[],"destacada":false},{"origen":"biblioteca","material":"2665b2eb-909d-4ff8-88aa-89150f0c6b18","detalle":"Con S. Saavedra-Messina y A. Silva-Riveros · Cuadernos de Investigación y Formación en Educación Matemática","conceptos":[],"destacada":false},{"origen":"biblioteca","material":"60c483ce-a8e9-4801-9fa8-34050bec024f","detalle":"Con P. Salazar-Cortez · Revista Chilena de Educación Científica","conceptos":[],"destacada":false},{"origen":"biblioteca","material":"d34e84cc-0530-44a8-ac4b-4d8c1ccb6842","detalle":"Con P. Salazar-Cortez · El Cálculo y su Enseñanza","conceptos":[],"destacada":false}]},{"clave":"convergencia","categoria":"modelacion","volanta":"La convergencia","color":"verde","periodo":"actualidad","composicion":"sintesis","titulo":"Modelación y tecnologías en ED.","texto":"En Empoderamiento Docente lidera el área de Modelación y Tecnologías: el punto donde su investigación sobre modelación matemática escolar y su trabajo con tecnologías se encuentran con el trabajo con docentes.","cita":"","hitos":[{"periodo":"","titulo":"Líder de Modelación y Tecnologías — Empoderamiento Docente","detalle":"","principal":true},{"periodo":"","titulo":"Académico del Departamento de Matemática — UMCE","detalle":"Proyectos de investigación y de vinculación con el medio escolar","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]}]', 'De la escuela a la modelación, y de vuelta al aula.', 'Su recorrido conecta las aulas de secundaria en Chile, la formación inicial de profesores en la UMCE y la investigación sobre modelación matemática escolar y tecnologías.', 'En ED esa trayectoria se pone al servicio de una pregunta concreta: cómo modelar situaciones reales, con tecnología, para que la matemática escolar tenga sentido.', true, CURRENT_TIMESTAMP),
  ('e7f82d2f-2051-4f53-963c-678efa37da33', 'judith-hernandez', 'Judith Hernández', 'Líder de proyecto · Currículum', 'México', 3, '{"src":"/equipo/judith-hernandez.jpg","alt":"Judith Hernández","foco":{"x":0.5,"y":0.25}}', false, 1.1, 1, 'Judith Alejandra Hernández Sánchez', 'Líder de proyecto · Currículum', 'Zacatecas, México', NULL, 'El currículum de matemáticas, mirado como objeto de estudio.', 'Doctora en Matemática Educativa y docente investigadora de tiempo completo en la Universidad Autónoma de Zacatecas. Investiga las dimensiones del currículum en matemáticas, la enseñanza del cálculo y el álgebra, y la formación de quienes se dedican a la matemática educativa.', '["Maestría en Matemática Aplicada — Universidad Autónoma de Zacatecas","Doctorado en Ciencias con especialidad en Matemática Educativa — Universidad Autónoma de Guerrero"]', '[{"clave":"curriculum","etiqueta":"Currículum en matemáticas","color":"naranja"},{"clave":"desarrollo-profesional","etiqueta":"Formación de profesionales","color":"verde"},{"clave":"investigacion","etiqueta":"Investigación en Matemática Educativa","color":"azul"}]', '{"tipo":"marco","foto":{"src":"/equipo/judith-hernandez.jpg","alt":"Judith Alejandra Hernández Sánchez","foco":{"x":0.5,"y":0.25}},"apaisado":false}', '[{"clave":"formacion","categoria":"investigacion","volanta":"La formación","color":"azul","periodo":"","composicion":"ficha","titulo":"De la matemática aplicada a la matemática educativa.","texto":"Se formó como maestra en Matemática Aplicada en la propia Universidad Autónoma de Zacatecas y se doctoró en Ciencias con especialidad en Matemática Educativa en la Universidad Autónoma de Guerrero.","cita":"","hitos":[{"periodo":"","titulo":"Maestría en Matemática Aplicada","detalle":"Universidad Autónoma de Zacatecas","principal":false},{"periodo":"","titulo":"Doctorado en Ciencias — Matemática Educativa","detalle":"Universidad Autónoma de Guerrero","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]},{"clave":"uaz","categoria":"desarrollo-profesional","volanta":"Una sola casa","color":"verde","periodo":"1993 – actualidad","composicion":"hitos","titulo":"Más de treinta años en la Universidad Autónoma de Zacatecas.","texto":"Es docente investigadora de tiempo completo, titular C, en la Unidad Académica de Matemáticas. Ahí sostiene la docencia, la investigación y el trabajo del cuerpo académico.","cita":"","hitos":[{"periodo":"1993 – actualidad","titulo":"Docente investigadora de tiempo completo, titular C","detalle":"Unidad Académica de Matemáticas, Universidad Autónoma de Zacatecas","principal":true},{"periodo":"","titulo":"Cuerpo Académico Consolidado «Matemática Educativa en la Profesionalización Docente»","detalle":"","principal":false},{"periodo":"2015","titulo":"Reconocimiento a perfil deseable","detalle":"PRODEP","principal":false},{"periodo":"2018","titulo":"Sistema Nacional de Investigadores","detalle":"","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]},{"clave":"curriculum","categoria":"curriculum","volanta":"Las líneas de investigación","color":"naranja","periodo":"","composicion":"editorial","titulo":"Qué se enseña, cómo se aprende y quién lo enseña.","texto":"Sus tres líneas de trabajo se sostienen desde hace años y se cruzan entre sí: el currículum, el cálculo y el álgebra, y la formación de quienes trabajan en el campo.","cita":"","hitos":[{"periodo":"","titulo":"El análisis de las dimensiones del currículum en matemáticas","detalle":"","principal":false},{"periodo":"","titulo":"La enseñanza y el aprendizaje del cálculo y el álgebra","detalle":"","principal":false},{"periodo":"","titulo":"La formación y el desarrollo de los profesionales de la matemática educativa","detalle":"","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]},{"clave":"produccion","categoria":"investigacion","volanta":"Producción reciente","color":"azul","periodo":"2023 – 2026","composicion":"ramas","titulo":"Los libros de texto, la planeación de clase y un libro propio.","texto":"Dos investigaciones con colegas de la propia unidad académica miran de cerca la tarea del libro de texto y la planeación con la que un profesor entra al aula. Un capítulo lleva GeoGebra al álgebra del bachillerato, y el libro que editó en 2026 reúne investigaciones para la formación docente en matemáticas.","cita":"","hitos":[],"ramas":[],"territorios":[],"publicaciones":[{"origen":"biblioteca","material":"58e0888f-db77-424f-a4f8-589bd791c114","detalle":"Edición, con David Alfonso Páez y Lilia Aké · Editorial SOMIDEM","conceptos":[],"destacada":false},{"origen":"biblioteca","material":"0614b3bc-1dc7-410d-b98b-3a741c2bfb93","detalle":"Con Eduardo Briceño · Revista de Investigación Educativa de la REDIECH","conceptos":[],"destacada":true},{"origen":"biblioteca","material":"a54c7956-793c-4cfe-ba28-1299a84cd36f","detalle":"Capítulo, con María Sofía Valero — Intervenciones educativas para la incidencia social · Universidad Autónoma de San Luis Potosí","conceptos":[],"destacada":false},{"origen":"biblioteca","material":"2e14b88e-8d13-4997-a8ca-91a558adee97","detalle":"Con C. Padilla y Eduardo Briceño · Revista Electrónica de Investigación Educativa","conceptos":[],"destacada":false}]},{"clave":"convergencia","categoria":"curriculum","volanta":"La convergencia","color":"verde","periodo":"actualidad","composicion":"sintesis","titulo":"Currículum en ED.","texto":"En Empoderamiento Docente lidera proyectos desde el análisis y el diseño del currículum en matemáticas.","cita":"","hitos":[{"periodo":"","titulo":"Líder de proyecto · Currículum — Empoderamiento Docente","detalle":"México","principal":true},{"periodo":"","titulo":"Red Cimates · CLAME · SOMIDEM","detalle":"","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]}]', 'Treinta años mirando la misma pregunta desde adentro.', 'Docencia e investigación en una sola universidad, con el currículum de matemáticas como objeto de estudio permanente.', NULL, true, CURRENT_TIMESTAMP),
  ('9ac1d35e-99e5-4e4c-a180-c013f4ce050f', 'gabriela-buendia', 'Gabriela Buendía', 'Líder de proyecto · Facilitadora', 'México', 3, '{"src":"/equipo/gabriela-buendia.jpg","alt":"Gabriela Buendía","foco":{"x":0.5,"y":0.22}}', false, 1.1, 2, 'Gabriela Buendía Ábalos', 'Líder de proyecto · Facilitadora y diseñadora de material didáctico', 'Ciudad de México', NULL, 'El saber matemático se construye en lo que la gente hace.', 'Doctora en Ciencias con especialidad en Matemática Educativa. Investiga cómo se construye socialmente el conocimiento matemático escolar a partir de sus usos, forma desde hace dos décadas a quienes investigan y enseñan, y edita la revista de la Red de Centros de Investigación en Matemática Educativa.', '["Licenciada en Actuaría — Facultad de Ciencias, UNAM","Maestra en Ciencias — Matemática Educativa, Cinvestav-IPN","Doctora en Ciencias — Matemática Educativa, Cinvestav-IPN"]', '[{"clave":"pensamiento-matematico","etiqueta":"Desarrollo del pensamiento matemático","color":"verde"},{"clave":"investigacion","etiqueta":"Investigación socioepistemológica","color":"azul"},{"clave":"formacion","etiqueta":"Formación de quienes investigan y enseñan","color":"verde"},{"clave":"materiales","etiqueta":"Libros y materiales para el aula","color":"naranja"}]', '{"tipo":"marco","foto":{"src":"/equipo/gabriela-buendia.jpg","alt":"Gabriela Buendía Ábalos","foco":{"x":0.5,"y":0.22}},"apaisado":false}', '[{"clave":"formacion","categoria":"investigacion","volanta":"De la actuaría a la Matemática Educativa","color":"azul","periodo":"1986 – 2004","composicion":"ficha","titulo":"Una tesis sobre lo periódico.","texto":"Estudió Actuaría en la UNAM y se formó como investigadora en el Cinvestav-IPN: una maestría sobre cómo se responde a tareas de probabilidad y un doctorado, dirigido por Francisco Cordero, sobre la periodicidad como construcción social. Esa tesis recibió el Premio Simón Bolívar 2005 del Comité Latinoamericano de Matemática Educativa a la mejor tesis de doctorado.","cita":"Una epistemología de la periodicidad en un marco de prácticas sociales","hitos":[{"periodo":"1993","titulo":"Licenciatura en Actuaría","detalle":"Facultad de Ciencias, UNAM","principal":false},{"periodo":"1994","titulo":"Maestría en Ciencias — Matemática Educativa","detalle":"Cinvestav-IPN","principal":false},{"periodo":"2004","titulo":"Doctorado en Ciencias — Matemática Educativa","detalle":"Cinvestav-IPN","principal":true}],"ramas":[{"periodo":"2005","lugar":"Comité Latinoamericano de Matemática Educativa","detalle":"Premio Simón Bolívar a la mejor tesis de doctorado"}],"territorios":[],"publicaciones":[]},{"clave":"socioepistemologia","categoria":"investigacion","volanta":"Cómo se construye el saber","color":"azul","periodo":"2005 – 2011","composicion":"concepto","titulo":"La construcción social del conocimiento matemático escolar.","texto":"Su investigación es socioepistemológica: estudia cómo se construye socialmente el conocimiento matemático que llega a la escuela, a partir de los usos y las prácticas donde ese saber tiene sentido. Lo periódico, las gráficas y la predicción fueron sus primeros casos. En 2011 reunió ese trabajo en un libro y coordinó un volumen colectivo de reflexión e investigación en Matemática Educativa. En esos años presidió la Red de Centros de Investigación en Matemática Educativa.","cita":"Articulando el saber matemático a través de prácticas sociales.","hitos":[{"periodo":"2011","titulo":"«La construcción social del conocimiento matemático escolar»","detalle":"Un estudio socioepistemológico sobre la periodicidad de las funciones · Díaz de Santos","principal":true},{"periodo":"2006 – 2009","titulo":"Presidenta de la Red de Centros de Investigación en Matemática Educativa","detalle":"","principal":false},{"periodo":"desde 2004","titulo":"Sistema Nacional de Investigadoras e Investigadores, nivel I","detalle":"Conahcyt, México","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]},{"clave":"tesis","categoria":"formacion","volanta":"Formar a quienes investigan","color":"verde","periodo":"2005 – actualidad","composicion":"hitos","titulo":"Casi treinta tesis dirigidas.","texto":"Ha dirigido tesis de especialidad, maestría y doctorado en la Universidad Autónoma de Chiapas, el CICATA-IPN, la Universidad Autónoma de Guerrero, la Universidad de Santo Tomás en Colombia y la Universidad Juárez del Estado de Durango. Varias fueron premiadas, y varias de sus tesistas —Paola Balda, hoy parte del equipo de ED; Isabel Tuyub; Fredy de la Cruz— son coautoras y coautores de sus artículos recientes.","cita":"","hitos":[{"periodo":"2011","titulo":"Mejor Tesis de Posgrado del IPN","detalle":"Como directora de la tesis doctoral de Verónica Molfino sobre la institucionalización del límite","principal":true},{"periodo":"2019","titulo":"Tesis laureada con mención especial","detalle":"Doctorado de Paola Balda · Universidad de Santo Tomás, Colombia","principal":false},{"periodo":"2009","titulo":"Mención honorífica en el Premio Simón Bolívar","detalle":"Tesis de maestría de Rosa Isela Vázquez · Comité Latinoamericano de Matemática Educativa","principal":false},{"periodo":"2005 – 2025","titulo":"Seis tesis doctorales, diecisiete de maestría y cinco de especialidad","detalle":"UNACH, CICATA-IPN, UAGro, Santo Tomás, UJED","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]},{"clave":"profesores","categoria":"materiales","volanta":"Escribir para quienes enseñan","color":"naranja","periodo":"2011 – 2016","composicion":"ramas","titulo":"Libros pensados para el aula.","texto":"Coordinó, con Marcela Ferrari y Gustavo Martínez, «Resignificación de funciones para profesores de matemáticas»: un libro escrito para acercar la investigación al trabajo cotidiano de quienes enseñan, con actividades de reflexión en cada capítulo. Ahí escribió sobre qué ves cuando te presentan una gráfica y, con Gisela Montiel, sobre el pensamiento funcional trigonométrico. Con el mismo espíritu participó en volúmenes sobre metodología de investigación, la dimensión histórica en la educación matemática y el comportamiento con tendencia.","cita":"","hitos":[],"ramas":[],"territorios":[],"publicaciones":[{"origen":"sin-link","titulo":"Resignificación de funciones para profesores de matemáticas","tipo":"Libros","anio":"2013","detalle":"Coordinación con M. Ferrari y G. Martínez · Díaz de Santos","conceptos":[],"destacada":true},{"origen":"sin-link","titulo":"¿Qué ves cuando te presentan una gráfica y te preguntan si es periódica?","tipo":"Capítulos de libro","anio":"2013","detalle":"Capítulo — Resignificación de funciones para profesores de matemáticas · Díaz de Santos","conceptos":[],"destacada":false},{"origen":"sin-link","titulo":"Desarrollo del pensamiento funcional trigonométrico","tipo":"Capítulos de libro","anio":"2013","detalle":"Con G. Montiel · Capítulo — Resignificación de funciones para profesores de matemáticas","conceptos":[],"destacada":false},{"origen":"sin-link","titulo":"Un esquema metodológico para la investigación socioepistemológica: ejemplos e ilustración","tipo":"Capítulos de libro","anio":"2012","detalle":"Con G. Montiel · Capítulo — Metodología en Matemática Educativa: visiones y reflexiones · Lectorum","conceptos":[],"destacada":false},{"origen":"sin-link","titulo":"From History to Research in Mathematics Education: socio-epistemological elements for trigonometric function","tipo":"Capítulos de libro","anio":"2011","detalle":"Con G. Montiel · Capítulo — Recent Developments on Introducing a Historical Dimension in Mathematics Education · Mathematical Association of America","conceptos":[],"destacada":false},{"origen":"sin-link","titulo":"El comportamiento con tendencia, lo estable y las ecuaciones diferenciales. Una argumentación gráfica","tipo":"Libros","anio":"2016","detalle":"Con F. Cordero, M. Solís, J. Mendoza y J. D. Zaldívar · Gedisa","conceptos":[],"destacada":false}]},{"clave":"usos","categoria":"pensamiento-matematico","volanta":"El saber en contextos reales","color":"verde","periodo":"2017 – actualidad","composicion":"ramas","titulo":"La tortilla, la huerta, el telebachillerato.","texto":"Sus investigaciones recientes buscan significados para la matemática escolar en los usos del conocimiento fuera de la escuela: la cocción de la tortilla de maíz como situación de aprendizaje, la periodicidad y lo proporcional en la huerta escolar, la enseñanza en zonas indígenas y en el telebachillerato chiapaneco. De ahí sale una propuesta de docencia basada en prácticas y usos del saber matemático, que hoy lleva a seminarios sobre educación matemática para la justicia social.","cita":"","hitos":[],"ramas":[],"territorios":[],"publicaciones":[{"origen":"biblioteca","material":"ca6871ff-b549-4112-b8dd-7f8648f8615a","detalle":"Con F. de la Cruz · Revista Latinoamericana de Investigación en Matemática Educativa","conceptos":[],"destacada":true},{"origen":"biblioteca","material":"3e3eb811-75b3-4c9d-a18b-a4841b7530de","detalle":"Con I. Tuyub y P. Balda · Tecné, Episteme y Didaxis","conceptos":[],"destacada":false},{"origen":"biblioteca","material":"31d5d001-a578-42ca-8283-80183ea6b5ef","detalle":"Con P. Balda · Revista Venezolana de Investigación en Educación Matemática","conceptos":[],"destacada":false},{"origen":"sin-link","titulo":"Docencia en matemáticas bajo la perspectiva socioepistemológica: diseños basados en prácticas y usos","tipo":"Artículos","anio":"2024","detalle":"Con J. Lezama y R. Flores · Cuadernos de Investigación y Formación en Educación Matemática","conceptos":[],"destacada":false},{"origen":"sin-link","titulo":"¿Ya está el pan? Una propuesta didáctica de variación y cambio para el aula de matemáticas","tipo":"Artículos","anio":"2019","detalle":"Con J. Lezama, A. Mata y T. Romero · Revista Práctica Docente","conceptos":[],"destacada":false}]},{"clave":"convergencia","categoria":"pensamiento-matematico","volanta":"La convergencia","color":"verde","periodo":"actualidad","composicion":"sintesis","titulo":"Investigar, editar, facilitar.","texto":"Es editora responsable de la revista Investigación e Innovación en Matemática Educativa, de la Red de Centros de Investigación en Matemática Educativa, y profesora-investigadora en la Universidad Juárez del Estado de Durango. En Empoderamiento Docente lidera proyectos y diseña y facilita material didáctico: el mismo saber, puesto a trabajar con docentes.","cita":"","hitos":[{"periodo":"","titulo":"Líder de proyecto, facilitadora y diseñadora de material didáctico — Empoderamiento Docente","detalle":"","principal":true},{"periodo":"","titulo":"Editora responsable — Investigación e Innovación en Matemática Educativa","detalle":"Red de Centros de Investigación en Matemática Educativa","principal":false},{"periodo":"","titulo":"Profesora-investigadora — Universidad Juárez del Estado de Durango","detalle":"Facultad de Ciencias Exactas · Maestría en Matemática Educativa","principal":false},{"periodo":"2024 – 2028","titulo":"Sistema Nacional de Investigadoras e Investigadores, nivel I","detalle":"","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]}]', 'Del saber que se usa, al saber que se enseña.', 'Su recorrido va de una tesis sobre lo periódico a veinte años de investigación socioepistemológica, de formar a quienes investigan, de libros escritos para profesores y de estudios en contextos reales como la tortilla o la huerta escolar.', 'En ED esa trayectoria se vuelve práctica: proyectos, facilitación y materiales para que el pensamiento matemático se desarrolle en el aula.', true, CURRENT_TIMESTAMP),
  ('5d8eb9d6-91eb-4569-b106-4e74372f4c96', 'marcela-cano', 'Marcela Cano', 'Líder de proyecto · Evaluación', 'México', 3, '{"src":"/equipo/marcela-cano.jpg","alt":"Marcela Cano","foco":{"x":0.5,"y":0.2}}', false, 1, 3, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, CURRENT_TIMESTAMP),
  ('2dde564a-f0c5-423f-896e-d41b2cb22bc0', 'luis-lopez', 'Luis López', 'Líder de Pensamiento Aritmético y Algebraico', 'Costa Rica', 3, '{"src":"/equipo/luis-lopez.jpg","alt":"Luis López","foco":{"x":0.5,"y":0.16}}', false, 1, 4, 'Luis Alberto López Acosta', 'Líder de Pensamiento Aritmético y Algebraico', 'San José, Costa Rica', 'Mérida, Yucatán, México', 'Del álgebra que se enseña, al álgebra que se construye.', 'Profesor de matemáticas e investigador en Matemática Educativa. Estudia cómo se construye socialmente el lenguaje algebraico y lleva esa investigación al aula, a la formación docente y a los libros de texto con los que se estudia.', '["Licenciado en Enseñanza de las Matemáticas — UADY","Maestro en Ciencias — Matemática Educativa, Cinvestav-IPN","Doctor en Ciencias — Matemática Educativa, Cinvestav-IPN"]', '[{"clave":"pensamiento-algebraico","etiqueta":"Pensamiento aritmético y algebraico","color":"verde"},{"clave":"investigacion","etiqueta":"Investigación en Matemática Educativa","color":"azul"},{"clave":"desarrollo-profesional","etiqueta":"Desarrollo profesional docente","color":"verde"},{"clave":"curriculo-materiales","etiqueta":"Currículo y materiales","color":"naranja"}]', '{"tipo":"marco","foto":{"src":"/equipo/luis-lopez.jpg","alt":"Luis Alberto López Acosta","foco":{"x":0.5,"y":0.5}},"apaisado":false}', '[{"clave":"aula","categoria":"desarrollo-profesional","volanta":"El aula como origen","color":"verde","periodo":"2011 – 2014","composicion":"editorial","titulo":"Primero, enseñar matemáticas en secundaria.","texto":"Se recibió de Licenciado en Enseñanza de las Matemáticas en la Universidad Autónoma de Yucatán y dio clases en secundaria y bachillerato. En paralelo ya diseñaba currículo para su propia facultad.","cita":"","hitos":[{"periodo":"2011","titulo":"Licenciatura en Enseñanza de las Matemáticas","detalle":"Universidad Autónoma de Yucatán","principal":false},{"periodo":"2012 – 2014","titulo":"Profesor de matemáticas de secundaria y bachillerato","detalle":"Club Preparatoriano, Yucatán","principal":false},{"periodo":"2011 – 2014","titulo":"Asesoría pedagógica y diseño curricular","detalle":"Facultad de Matemáticas UADY, en convenio con la Secretaría de Educación de Yucatán","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]},{"clave":"formacion","categoria":"desarrollo-profesional","volanta":"Formar a quienes enseñan","color":"naranja","periodo":"2015 – 2018","composicion":"hitos","titulo":"El programa que formó a miles de docentes en México.","texto":"En el Programa Interdisciplinario para el Desarrollo Profesional Docente en Matemáticas (SEP-Cinvestav) diseñó e impartió cursos de formación. Entre ellos, «Empoderamiento docente»: la misma línea de trabajo que después le daría nombre a ED.","cita":"","hitos":[{"periodo":"2016","titulo":"Curso «Empoderamiento docente: proceso de desarrollo profesional»","detalle":"Coordinación académica, diseño e instrucción — SEP-Cinvestav","principal":true},{"periodo":"2016","titulo":"Curso «Problematización de la Matemática Escolar»","detalle":"Diseño e instrucción — SEP-Cinvestav","principal":false},{"periodo":"2015 – 2016","titulo":"Talleres de desarrollo profesional docente en Matemáticas","detalle":"Tres generaciones, educación media superior — SEP-Cinvestav","principal":false},{"periodo":"2016 – 2017","titulo":"Programa PODER","detalle":"Diseño e instrucción — atención a la deserción escolar en media superior","principal":false},{"periodo":"2017 – 2018","titulo":"Diplomado Sentido Numérico y Pensamiento Algebraico","detalle":"Instructor — IPN-SEP","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]},{"clave":"posgrado","categoria":"investigacion","volanta":"Investigar el lenguaje del álgebra","color":"azul","periodo":"2014 – 2023","composicion":"ficha","titulo":"Maestría y doctorado en Matemática Educativa.","texto":"Cursó ambos posgrados en el Cinvestav-IPN con beca del Conacyt. Su investigación cruza la socioepistemología con la lingüística sistémico-funcional para estudiar cómo se construyó el lenguaje algebraico —de Viète y Descartes en adelante— y qué implica eso para enseñarlo.","cita":"","hitos":[{"periodo":"2016","titulo":"Maestría en Ciencias — Matemática Educativa","detalle":"Cinvestav-IPN","principal":false},{"periodo":"2023","titulo":"Doctorado en Ciencias — Matemática Educativa","detalle":"Cinvestav-IPN","principal":false}],"ramas":[{"periodo":"2018 – 2019","lugar":"UNAM","detalle":"Formación en Lingüística Sistémico-Funcional, Maestría en Lingüística Aplicada"}],"territorios":[],"publicaciones":[]},{"clave":"materiales","categoria":"curriculo-materiales","volanta":"Escribir para el aula","color":"naranja","periodo":"2015 – actualidad","composicion":"ramas","titulo":"Los libros con los que se estudia.","texto":"Es coautor de los libros de Matemáticas de primero a cuarto grado de primaria de la Secretaría de Educación de Yucatán, escribió un capítulo de la colección Matemática en Red que coordinó Daniela Reyes para el Ministerio de Educación porteño, y desde 2023 asesora los contenidos de los libros de texto de ese mismo ministerio.","cita":"","hitos":[],"ramas":[],"territorios":[],"publicaciones":[{"origen":"sin-link","titulo":"Producción de fórmulas","tipo":"Capítulos de libro","anio":"2024","detalle":"Capítulo — Colección Matemática en Red, Tomo I · Ministerio de Educación de la Ciudad de Buenos Aires","conceptos":[],"destacada":true},{"origen":"sin-link","titulo":"Matemáticas, 1.º a 4.º grado de primaria","tipo":"Materiales","anio":"2015 – 2017","detalle":"Coautoría — Secretaría de Educación del Gobierno del Estado de Yucatán","conceptos":[],"destacada":false},{"origen":"biblioteca","material":"98f2912d-998e-439e-b547-47a723391b00","detalle":"Con F. Romero · Cuadernos de Investigación y Formación en Educación Matemática","conceptos":[],"destacada":false},{"origen":"biblioteca","material":"27b83406-3c00-4564-a07b-e615a5131a53","detalle":"Revista Venezolana de Investigación en Educación Matemática","conceptos":[],"destacada":false},{"origen":"biblioteca","material":"4546bd82-c5e1-4fd5-ad30-47f64f6278cc","detalle":"","conceptos":[],"destacada":false},{"origen":"biblioteca","material":"1548927f-ea7c-40a7-84e9-f20eac88d005","detalle":"Con G. Montiel · Góndola, Enseñanza y Aprendizaje de las Ciencias","conceptos":[],"destacada":false}]},{"clave":"costa-rica","categoria":"desarrollo-profesional","volanta":"Formación docente en Costa Rica","color":"azul","periodo":"2021 – actualidad","composicion":"hitos","titulo":"De Yucatán a la Universidad de Costa Rica.","texto":"Es profesor de la Escuela de Formación Docente de la Universidad de Costa Rica, donde dirige trabajos finales de graduación y coordina las actividades académicas de enseñanza de la matemática.","cita":"","hitos":[{"periodo":"2024 – actualidad","titulo":"Profesor de tiempo completo — Escuela de Formación Docente","detalle":"Universidad de Costa Rica","principal":true},{"periodo":"2023 – 2024","titulo":"Profesor visitante","detalle":"Universidad de Costa Rica","principal":false},{"periodo":"2021 – 2022","titulo":"Profesor de carrera de enseñanza superior","detalle":"Universidad Autónoma de Yucatán","principal":false},{"periodo":"2024","titulo":"Coordinación de la I Escuela de Verano de Enseñanza de la Matemática","detalle":"Universidad de Costa Rica","principal":false},{"periodo":"2023","titulo":"Coordinación del IV Día de la Enseñanza de la Matemática","detalle":"Universidad de Costa Rica","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]},{"clave":"convergencia","categoria":"pensamiento-algebraico","volanta":"La convergencia","color":"verde","periodo":"actualidad","composicion":"sintesis","titulo":"Pensamiento aritmético y algebraico en ED.","texto":"En Empoderamiento Docente lidera la línea de pensamiento aritmético y algebraico: el punto donde su investigación sobre el lenguaje del álgebra se encuentra con el trabajo con docentes.","cita":"","hitos":[{"periodo":"","titulo":"Líder de Pensamiento Aritmético y Algebraico — Empoderamiento Docente","detalle":"","principal":true},{"periodo":"desde 2017","titulo":"Miembro asociado del Comité Latinoamericano de Matemática Educativa","detalle":"","principal":false},{"periodo":"desde 2019","titulo":"Miembro de ALSFAL","detalle":"Asociación de Lingüística Sistémico-Funcional de América Latina","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]}]', 'Investigar el lenguaje para enseñar mejor.', 'Su recorrido conecta el aula de secundaria, la formación de docentes en México, la investigación sobre pensamiento y lenguaje algebraico y la escritura de materiales para primaria y secundaria.', 'En ED esa trayectoria se pone al servicio de una pregunta concreta: cómo se construye el pensamiento aritmético y algebraico en la escuela.', true, CURRENT_TIMESTAMP),
  ('89ea5eb0-3504-47fc-b524-7e94efa58171', 'andrea-vergara', 'Andrea Vergara', 'Líder de Pensamiento Estadístico', 'Chile', 3, '{"src":"/equipo/andrea-vergara.jpg","alt":"Andrea Vergara","foco":{"x":0.72,"y":0.5}}', false, 1, 5, 'Andrea Vergara-Gómez', 'Líder de Pensamiento Estadístico', 'Talca, Chile', NULL, 'Decidir con incertidumbre también se aprende.', 'Profesora de Matemática, magíster y doctora en Didáctica de la Matemática. Investiga la toma de decisiones en contextos de riesgo e incertidumbre como un saber matemático escolar, y forma profesorado en la Universidad Católica del Maule.', '["Profesora de Matemáticas y Licenciada en Educación — PUCV","Magíster en Didáctica de la Matemática — PUCV","Doctora en Didáctica de la Matemática — PUCV"]', '[{"clave":"pensamiento-estadistico","etiqueta":"Pensamiento estadístico y probabilístico","color":"verde"},{"clave":"formacion-docente","etiqueta":"Formación del profesorado","color":"azul"},{"clave":"investigacion","etiqueta":"Investigación en educación matemática","color":"azul"}]', '{"tipo":"marco","foto":{"src":"/equipo/andrea-vergara.jpg","alt":"Andrea Vergara-Gómez","foco":{"x":0.5,"y":0.5}},"apaisado":true}', '[{"clave":"valparaiso","categoria":"formacion-docente","volanta":"Valparaíso","color":"verde","periodo":"2003 – 2007","composicion":"ficha","titulo":"Profesora de Matemáticas, primero.","texto":"Se formó en el Instituto de Matemáticas de la Pontificia Universidad Católica de Valparaíso, la casa donde después investigaría y enseñaría durante más de una década.","cita":"","hitos":[{"periodo":"2003 – 2007","titulo":"Profesora de Matemáticas y Licenciada en Educación","detalle":"Pontificia Universidad Católica de Valparaíso","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]},{"clave":"docencia","categoria":"formacion-docente","volanta":"Enseñar a enseñar","color":"azul","periodo":"2012 – 2021","composicion":"hitos","titulo":"Casi diez años formando profesorado.","texto":"Fue docente del Instituto de Matemáticas de la PUCV y, más tarde, de la Facultad de Pedagogía de la Universidad Academia de Humanismo Cristiano, en Santiago.","cita":"","hitos":[{"periodo":"2012 – 2020","titulo":"Docente — Instituto de Matemáticas, Facultad de Ciencias","detalle":"Pontificia Universidad Católica de Valparaíso","principal":true},{"periodo":"2019 – 2021","titulo":"Docente — Facultad de Pedagogía","detalle":"Universidad Academia de Humanismo Cristiano, Santiago","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]},{"clave":"posgrado","categoria":"investigacion","volanta":"La didáctica como campo","color":"azul","periodo":"2013 – 2020","composicion":"ficha","titulo":"Magíster y doctora en Didáctica de la Matemática.","texto":"Cursó los dos posgrados en el Instituto de Matemáticas de la PUCV mientras seguía dando clases.","cita":"","hitos":[{"periodo":"2013 – 2015","titulo":"Magíster en Didáctica de la Matemática","detalle":"PUCV","principal":false},{"periodo":"2016 – 2020","titulo":"Doctora en Didáctica de la Matemática","detalle":"PUCV","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]},{"clave":"ucm","categoria":"formacion-docente","volanta":"Investigación con nombre propio","color":"verde","periodo":"2021 – actualidad","composicion":"editorial","titulo":"Universidad Católica del Maule.","texto":"Es Profesora Auxiliar de la Facultad de Ciencias Básicas e investigadora del CIEMAE, el Centro de Investigación en Educación Matemática y Estadística.","cita":"","hitos":[{"periodo":"2021 – actualidad","titulo":"Profesora Auxiliar — Departamento de Matemática, Física y Estadística","detalle":"Facultad de Ciencias Básicas, Universidad Católica del Maule","principal":true},{"periodo":"","titulo":"Académica e investigadora","detalle":"CIEMAE — Centro de Investigación en Educación Matemática y Estadística","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]},{"clave":"incertidumbre","categoria":"pensamiento-estadistico","volanta":"La línea de trabajo","color":"azul","periodo":"","composicion":"ramas","titulo":"Decidir en contextos de riesgo e incertidumbre.","texto":"Su investigación toma la decisión bajo incertidumbre como un saber matemático escolar: qué se pone en juego al decidir, cómo se evalúa y con qué situaciones —un dilema clásico, un juego de mesa— se puede enseñar.","cita":"","hitos":[],"ramas":[],"territorios":[],"publicaciones":[{"origen":"biblioteca","material":"b96b56bd-8834-4566-beb1-8fcb1ffb16d5","detalle":"","conceptos":[],"destacada":true},{"origen":"biblioteca","material":"9940954b-d28d-4b5e-a6b2-1bc68b02e053","detalle":"Eurasia Journal of Mathematics, Science and Technology Education","conceptos":[],"destacada":false},{"origen":"biblioteca","material":"62003079-f286-4a34-bc53-a8ee4437b734","detalle":"Horizontes. Revista de Investigación en Ciencias de la Educación","conceptos":[],"destacada":false},{"origen":"biblioteca","material":"e9a0e2b3-dfa5-4a09-9c58-b1038e70e7df","detalle":"Revista de Estudios y Experiencias en Educación","conceptos":[],"destacada":false}]},{"clave":"convergencia","categoria":"pensamiento-estadistico","volanta":"La convergencia","color":"verde","periodo":"actualidad","composicion":"sintesis","titulo":"Pensamiento estadístico en ED.","texto":"En Empoderamiento Docente lidera la línea de pensamiento estadístico: lo que la investigación sabe sobre azar, riesgo y decisión, puesto a trabajar con docentes.","cita":"","hitos":[{"periodo":"","titulo":"Líder de Pensamiento Estadístico — Empoderamiento Docente","detalle":"Chile","principal":true}],"ramas":[],"territorios":[],"publicaciones":[]}]', 'De la formación inicial a la investigación aplicada.', 'Veinte años en la misma pregunta, vista desde el aula universitaria, el posgrado y la investigación: cómo se enseña a razonar cuando no hay certeza.', NULL, true, CURRENT_TIMESTAMP),
  ('48d2957c-29d0-44d2-8cfa-af3578535ae6', 'wendolyne-rios', 'Wendolyne Ríos', 'Facilitadora y diseñadora de material didáctico', 'México', 4, '{"src":"/equipo/wendolyne-rios.jpg","alt":"Wendolyne Ríos","foco":{"x":0.5,"y":0.2}}', false, 1, 0, 'Diana Wendolyne Ríos Jarquín', 'Facilitadora y diseñadora de material didáctico', 'Ciudad de México, México', 'Nezahualcóyotl, Estado de México', 'Formar a quienes forman, desde el saber matemático transversal.', 'Licenciada en Física y Matemáticas y maestra en Matemática Educativa. Investiga la formación de formadores y la transversalidad del saber matemático, edita la principal revista de investigación del campo en la región y diseña los materiales que llegan al aula.', '["Licenciada en Física y Matemáticas — ESFM del IPN","Maestra en Ciencias — Matemática Educativa, Cinvestav-IPN","Doctorado en Ciencias — Matemática Educativa, Cinvestav-IPN (en curso)","Diplomado en Edición de Revistas Académicas — IISUE, UNAM"]', '[{"clave":"transversalidad","etiqueta":"Transversalidad del saber matemático","color":"verde"},{"clave":"formacion-formadores","etiqueta":"Formación de formadores","color":"verde"},{"clave":"edicion","etiqueta":"Edición científica","color":"azul"},{"clave":"materiales","etiqueta":"Materiales para el aula","color":"naranja"}]', '{"tipo":"marco","foto":{"src":"/equipo/wendolyne-rios.jpg","alt":"Diana Wendolyne Ríos Jarquín","foco":{"x":0.5,"y":0.2}},"apaisado":false}', '[{"clave":"formacion","categoria":"transversalidad","volanta":"De la física a la matemática educativa","color":"azul","periodo":"2013 – actualidad","composicion":"ficha","titulo":"Una pregunta que se fue haciendo más grande.","texto":"Estudió Física y Matemáticas en la ESFM del IPN y siguió con la maestría en el Cinvestav. Su tesis de licenciatura miró las dificultades comunes con la noción de función; la de maestría, la transversalidad de tres teoremas fundamentales.","cita":"","hitos":[{"periodo":"2013 – 2017","titulo":"Licenciatura en Física y Matemáticas","detalle":"ESFM del Instituto Politécnico Nacional","principal":false},{"periodo":"2017 – 2020","titulo":"Maestría en Ciencias — Matemática Educativa","detalle":"Cinvestav-IPN","principal":false},{"periodo":"2020 – actualidad","titulo":"Doctorado en Ciencias — Matemática Educativa","detalle":"Cinvestav-IPN, en curso","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]},{"clave":"relime","categoria":"edicion","volanta":"La revista del campo","color":"azul","periodo":"2016 – actualidad","composicion":"hitos","titulo":"Casi diez años haciendo RELIME.","texto":"Entró a la Coordinación Técnica de la Revista Latinoamericana de Investigación en Matemática Educativa y desde 2019 es editora. En el camino se formó en edición de revistas académicas en la UNAM.","cita":"","hitos":[{"periodo":"2019 – actualidad","titulo":"Editora — Revista Latinoamericana de Investigación en Matemática Educativa","detalle":"Comité Latinoamericano de Matemática Educativa","principal":true},{"periodo":"2016 – 2019","titulo":"Coordinación Técnica de RELIME","detalle":"","principal":false},{"periodo":"2018 – 2019","titulo":"Diplomado en Edición de Revistas Académicas","detalle":"IISUE, UNAM","principal":false},{"periodo":"2025 – actualidad","titulo":"Coordinación de Comunicación y Redes","detalle":"Red de Centros de Investigación en Matemática Educativa","principal":false},{"periodo":"2015 – 2017","titulo":"Becaria ayudante de investigador","detalle":"Cinvestav-IPN","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]},{"clave":"materiales","categoria":"materiales","volanta":"Escribir para el aula","color":"naranja","periodo":"2017 – 2019","composicion":"ramas","titulo":"Los cuadernos del Plan Nacional Aprender Matemática.","texto":"Fue asesora, facilitadora y diseñadora en el Programa Interdisciplinario para el Desarrollo Profesional Docente en Matemáticas y después tutora y diseñadora de materiales del Plan Nacional Aprender Matemática, en Argentina.","cita":"","hitos":[],"ramas":[],"territorios":[],"publicaciones":[{"origen":"biblioteca","material":"77e32742-f657-4908-8491-ea501f0b05f0","detalle":"Coautoría de la colección · Ministerio de Educación, Cultura, Ciencia y Tecnología de Argentina","conceptos":["Aproximar y optimizar","Medir","Comparar y equivaler","Inferir"],"destacada":true},{"origen":"biblioteca","material":"7de4adf0-675d-4719-9abe-8606e214b636","detalle":"Con R. Cantoral y otros · Revista Latinoamericana de Investigación en Matemática Educativa","conceptos":[],"destacada":false}]},{"clave":"docencia","categoria":"formacion-formadores","volanta":"Enseñar a enseñar","color":"verde","periodo":"2020 – actualidad","composicion":"hitos","titulo":"Especialidad, diplomado y seis tesis dirigidas.","texto":"Da clases en la Especialidad en Matemática Educativa de la Benemérita Escuela Normal Veracruzana y en el Diplomado en Matemática Educativa de la UDLA en Chile, y dirige los trabajos de graduación de docentes en ejercicio.","cita":"","hitos":[{"periodo":"2020 – actualidad","titulo":"Tutora y profesora — Especialidad en Matemática Educativa","detalle":"Benemérita Escuela Normal Veracruzana","principal":true},{"periodo":"2022 – 2024","titulo":"Desarrollo del Pensamiento y Lenguaje Variacional","detalle":"Diplomado en Matemática Educativa — Universidad De Las Américas, Chile","principal":false},{"periodo":"2022 – 2025","titulo":"Dirección de seis tesis de especialidad","detalle":"Veracruz, México","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]},{"clave":"doctorado","categoria":"formacion-formadores","volanta":"La investigación en curso","color":"verde","periodo":"","composicion":"concepto","titulo":"Qué le pasa a quien forma a otros.","texto":"Su proyecto doctoral estudia el proceso de empoderamiento en la formación de formadores: no el de quien aprende matemática por primera vez, sino el de quien tiene que enseñar a enseñarla.","cita":"Formación de formadores: un estudio del proceso de empoderamiento desde el saber matemático transversal.","hitos":[{"periodo":"2017","titulo":"Tesis de licenciatura — la noción de función en estudiantes de Física y Matemáticas","detalle":"","principal":false},{"periodo":"2020","titulo":"Tesis de maestría — Socioepistemología y transversalidad","detalle":"","principal":false},{"periodo":"en desarrollo","titulo":"Proyecto doctoral — formación de formadores y empoderamiento","detalle":"","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]},{"clave":"convergencia","categoria":"materiales","volanta":"La convergencia","color":"verde","periodo":"2021 – actualidad","composicion":"sintesis","titulo":"Fortalecimiento en Matemáticas, en ED.","texto":"Desde 2021 es profesora y diseñadora del Proyecto de Fortalecimiento en Matemáticas de Empoderamiento Docente.","cita":"","hitos":[{"periodo":"2021 – actualidad","titulo":"Profesora y diseñadora — Proyecto de Fortalecimiento en Matemáticas, Empoderamiento Docente","detalle":"","principal":true},{"periodo":"","titulo":"Facilitadora y diseñadora de material didáctico","detalle":"","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]}]', 'Editar, diseñar y enseñar la misma matemática.', 'La revista donde se publica la investigación del campo, los materiales que llegan al aula y las clases con docentes en ejercicio son tres caras del mismo trabajo.', NULL, true, CURRENT_TIMESTAMP),
  ('115ebaa2-0bd1-4a21-bb9e-a7992a7acf5a', 'pedro-vidal-szabo', 'Pedro Vidal-Szabó', 'Facilitador · Pensamiento estocástico', 'Chile', 4, '{"src":"/equipo/pedro-vidal-szabo.jpg","alt":"Pedro Vidal-Szabó","foco":{"x":0.5,"y":0.12}}', false, 1.22, 1, 'Pedro Vidal-Szabó', 'Facilitador · Pensamiento estocástico', 'Chile', NULL, 'Convertir los datos en visiones del mundo.', 'Profesor de Matemática con mención en Estadística Educacional, magíster y doctor en Didáctica de la Matemática. Investiga cómo razonan con datos niñas y niños desde los primeros grados y qué necesita saber quien les enseña estadística, y coordinó programas públicos de formación docente que llegaron a más de cien escuelas de Chile.', '["Licenciado en Educación Matemática — UMCE","Profesor de Matemática, mención Estadística Educacional — UMCE","Postítulo en Didáctica de la Matemática — Instituto de Matemáticas, PUCV","Magíster en Didáctica de la Matemática — Instituto de Matemáticas, PUCV","Doctor en Didáctica de la Matemática — Instituto de Matemáticas, PUCV"]', '[{"clave":"estadistica-temprana","etiqueta":"Estadística temprana","color":"verde"},{"clave":"conocimiento-profesor","etiqueta":"Conocimiento del profesor de estadística","color":"azul"},{"clave":"formacion-escala","etiqueta":"Formación docente a escala","color":"naranja"},{"clave":"universidad","etiqueta":"Docencia universitaria","color":"azul"}]', '{"tipo":"marco","foto":{"src":"/equipo/pedro-vidal-szabo.jpg","alt":"Pedro Vidal-Szabó","foco":{"x":0.5,"y":0.12}},"apaisado":false}', '[{"clave":"umce","categoria":"universidad","volanta":"Santiago","color":"verde","periodo":"2009 – 2014","composicion":"hitos","titulo":"Profesor de Matemática, con la estadística como mención.","texto":"Se formó en la Universidad Metropolitana de Ciencias de la Educación. Todavía estudiante, integró la comisión académica de la agrupación de estudiantes de pedagogía en matemática y un equipo de investigación-acción, Espiral Educativo, que ganó dos proyectos para trabajar GeoGebra y origami modular con profesores. Después dio clases de matemática en la enseñanza media.","cita":"","hitos":[{"periodo":"2013","titulo":"Profesor de Matemática, mención Estadística Educacional","detalle":"Universidad Metropolitana de Ciencias de la Educación · Licenciado en Educación Matemática en 2012","principal":true},{"periodo":"2010 – 2013","titulo":"Equipo Espiral Educativo — investigación-acción en educación matemática","detalle":"UMCE · dos proyectos del Fondo de Desarrollo Institucional del Ministerio de Educación, ejecutados en 2012","principal":false},{"periodo":"2013 – 2014","titulo":"Profesor de matemática, 1° a 4° medio","detalle":"Colegio Leonardo Da Vinci, Las Condes","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]},{"clave":"valparaiso","categoria":"conocimiento-profesor","volanta":"Valparaíso","color":"azul","periodo":"2014 – 2022","composicion":"ficha","titulo":"Postítulo, magíster y doctorado en la misma casa.","texto":"Cursó los tres posgrados en el Instituto de Matemáticas de la Pontificia Universidad Católica de Valparaíso, los dos últimos con beca CONICYT. En el medio dio clases en el propio magíster.","cita":"","hitos":[{"periodo":"2014","titulo":"Postítulo en Didáctica de la Matemática","detalle":"Instituto de Matemáticas, PUCV","principal":false},{"periodo":"2015","titulo":"Magíster en Didáctica de la Matemática","detalle":"Instituto de Matemáticas, PUCV · beca CONICYT para Profesionales de la Educación","principal":false},{"periodo":"2022","titulo":"Doctor en Didáctica de la Matemática","detalle":"Instituto de Matemáticas, PUCV · beca CONICYT de Doctorado Nacional","principal":true}],"ramas":[{"periodo":"2018 – 2019","lugar":"Magíster PUCV","detalle":"Docente del Magíster en Didáctica de la Matemática: fundamentos, marcos teóricos y talleres de investigación"}],"territorios":[],"publicaciones":[]},{"clave":"estadistica-temprana","categoria":"estadistica-temprana","volanta":"La línea de investigación","color":"azul","periodo":"2015 – actualidad","composicion":"ramas","titulo":"Cómo razonan con datos niñas y niños desde los primeros grados.","texto":"Integra el Grupo de Investigación en Estadística Temprana que dirige Soledad Estrella. Con ella participó en dos proyectos FONDECYT sobre representaciones de datos y razonamiento inferencial informal de kínder a cuarto básico, y en el proyecto Mejor Matemática del CIAE. Su tesis extendió a la estadística el modelo del conocimiento especializado del profesor de matemáticas: qué necesita saber quien enseña a leer datos.","cita":"La estadística involucra convertir los datos en visiones del mundo real.","hitos":[],"ramas":[],"territorios":[],"publicaciones":[{"origen":"biblioteca","material":"5758266f-172e-427b-b6e8-f912fcb92e57","detalle":"Educación Matemática, 32(2) · con Kuzniak, Estrella y Montoya","conceptos":[],"destacada":true},{"origen":"biblioteca","material":"8ecfeba5-dca5-43c6-946c-298e9884fed5","detalle":"Educación Matemática, 35(2) · con Parraguez, Bonilla y Campos","conceptos":[],"destacada":false},{"origen":"biblioteca","material":"83f2a769-d753-4892-bd6e-788b1a670db8","detalle":"Revista de Educación Estadística, 2(1) · con Estrella","conceptos":[],"destacada":false},{"origen":"biblioteca","material":"d1600bb7-2a4d-4a58-b1e5-1591c04d2334","detalle":"RELIME, 27(1) · Estrella, Morales, Méndez-Reina, Vidal-Szabó, Ramírez y Mondaca-Saavedra","conceptos":[],"destacada":false},{"origen":"biblioteca","material":"deaadc77-e97c-4166-bec9-6a3ebb27b8d8","detalle":"Educación Matemática, 37(2) · Estrella, Ramírez, Mondaca-Saavedra, Méndez-Reina, Vidal-Szabó y Morales","conceptos":[],"destacada":false}]},{"clave":"sumo-primero","categoria":"formacion-escala","volanta":"Política pública","color":"naranja","periodo":"2012 – 2024","composicion":"hitos","titulo":"Sumo Primero en Terreno: acompañar el aula a escala.","texto":"Programa del Ministerio de Educación de Chile para acompañar en el aula a quienes enseñan matemática de primero a cuarto básico. Entró como tutor y coordinador regional con la PUCV, siguió como coordinador pedagógico con la Universidad del Desarrollo y terminó dirigiéndolo académicamente para la macrozona que va de la Región Metropolitana al Biobío. Antes había dado talleres y asesorías a escuelas por su cuenta.","cita":"","hitos":[{"periodo":"2023 – 2024","titulo":"Director académico, macrozona 2 — Sumo Primero en Terreno","detalle":"Universidad del Desarrollo · MINEDUC · cerca de 1000 docentes, 130 escuelas y más de 15 000 estudiantes","principal":true},{"periodo":"2020 – 2023","titulo":"Coordinador pedagógico — Sumo Primero en Terreno","detalle":"Universidad del Desarrollo · MINEDUC · 880 docentes de 130 establecimientos","principal":false},{"periodo":"2019 – 2021","titulo":"Tutor y coordinador regional — Sumo Primero en Terreno","detalle":"PUCV · MINEDUC · acompañamiento en 4 escuelas y coordinación de 30 escuelas de la Región Metropolitana","principal":false},{"periodo":"2012 – 2015","titulo":"Talleres y asesorías a escuelas","detalle":"Método Singapur (VirtuaLab, USACH), asesoría en didáctica de la matemática (ATE Universidad de Concepción) y Laboratorio de GeoGebra Experimental (Fundación Belén Educa)","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]},{"clave":"universidad","categoria":"universidad","volanta":"Formar a quienes van a enseñar","color":"azul","periodo":"2015 – actualidad","composicion":"hitos","titulo":"Formación inicial docente, de Santiago a Osorno.","texto":"Enseña didáctica de la matemática y de la estadística a futuros profesores y profesoras y a docentes en ejercicio. Coordinó el área de Matemática de los programas de formación pedagógica de la Universidad del Desarrollo y hoy es investigador y académico de la Universidad de Los Lagos.","cita":"","hitos":[{"periodo":"actualidad","titulo":"Investigador y académico","detalle":"Universidad de Los Lagos, sede Osorno","principal":true},{"periodo":"2023 – 2025","titulo":"Coordinador del área de Matemática de los programas de formación docente","detalle":"Facultad de Educación, Universidad del Desarrollo","principal":false},{"periodo":"2024 – 2025","titulo":"Académico colaborador — Magíster en Didáctica de la Matemática","detalle":"Universidad Alberto Hurtado · línea de didáctica de la estadística y guía de tesis","principal":false},{"periodo":"2025","titulo":"Académico — Facultad de Educación","detalle":"Universidad Católica Silva Henríquez · seminario de grado y práctica profesional","principal":false},{"periodo":"2015","titulo":"Docente — Programa de Formación Pedagógica","detalle":"Universidad del Desarrollo · didáctica de la matemática, prácticas y Laboratorio de GeoGebra Experimental","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]},{"clave":"convergencia","categoria":"estadistica-temprana","volanta":"La convergencia","color":"verde","periodo":"2021 – actualidad","composicion":"sintesis","titulo":"Pensamiento estocástico en ED.","texto":"Llegó a Empoderamiento Docente en 2021 como diseñador y relator de cursos de desarrollo profesional para docentes de Latinoamérica. Hoy facilita y diseña material didáctico sobre pensamiento estocástico: azar, datos y decisiones, trabajados desde el saber de quien enseña.","cita":"","hitos":[{"periodo":"2021 – actualidad","titulo":"Facilitador y diseñador de material didáctico · Pensamiento estocástico — Empoderamiento Docente","detalle":"Chile","principal":true},{"periodo":"","titulo":"Revisor científico","detalle":"RELIME, RECHIEM, Revista de Educación Estadística, Aula Abierta y Revista Mexicana de Psicología, entre otras","principal":false},{"periodo":"","titulo":"Miembro","detalle":"SOCHIEM, Grupo de Estudio de Clase, RIITMA, Red MTSK y Grupo de Investigación en Estadística Temprana","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]}]', 'Del aula de enseñanza media a la estadística temprana.', 'Un mismo hilo une la tesis, los proyectos de investigación y los programas con cientos de escuelas: entender cómo se aprende a razonar con datos y acompañar a quienes lo enseñan.', NULL, true, CURRENT_TIMESTAMP),
  ('3da1ad79-9d0e-47a9-b72d-e3207108c241', 'paola-balda', 'Paola Balda', 'Facilitadora · Pensamiento proporcional', 'Colombia', 4, '{"src":"/equipo/paola-balda.jpg","alt":"Paola Balda","foco":{"x":0.5,"y":0.28}}', false, 1, 2, 'Paola Alejandra Balda Álvarez', 'Facilitadora · Pensamiento proporcional', 'Soacha, Cundinamarca, Colombia', NULL, 'Veinte años en la misma escuela, investigando desde adentro.', 'Licenciada en Matemáticas y doctora en Educación, con tesis laureada sobre los usos de lo proporcional. Da clases en una escuela pública de Soacha desde hace dos décadas y desde ahí investiga, forma profesorado y organiza festivales matemáticos.', '["Licenciada en Matemáticas — Universidad Distrital Francisco José de Caldas","Magíster en Docencia de las Matemáticas — Universidad Pedagógica Nacional","Doctora en Educación — Universidad Santo Tomás","Especialista en Gerencia Educativa — Universidad San Buenaventura"]', '[{"clave":"pensamiento-proporcional","etiqueta":"Pensamiento proporcional","color":"verde"},{"clave":"aula","etiqueta":"El aula como escenario","color":"verde"},{"clave":"formacion-docente","etiqueta":"Formación docente","color":"azul"},{"clave":"justicia-social","etiqueta":"Matemáticas y justicia social","color":"naranja"}]', '{"tipo":"marco","foto":{"src":"/equipo/paola-balda.jpg","alt":"Paola Alejandra Balda Álvarez","foco":{"x":0.5,"y":0.28}},"apaisado":false}', '[{"clave":"aula","categoria":"aula","volanta":"El punto fijo","color":"verde","periodo":"2005 – actualidad","composicion":"hitos","titulo":"Dos décadas en la Institución Educativa General Santander.","texto":"Todo su recorrido tiene el mismo punto fijo: el aula de una escuela pública de Soacha. Ahí nacieron sus proyectos, ahí se probaron y desde ahí se investigaron.","cita":"","hitos":[{"periodo":"2005 – actualidad","titulo":"Profesora de matemáticas — I.E. General Santander, Soacha","detalle":"Docente de planta, Secretaría de Educación de Soacha","principal":true},{"periodo":"2006 – 2011","titulo":"Club de Matemáticas","detalle":"Experiencia significativa, segundo lugar en el Foro Municipal de Educación","principal":false},{"periodo":"2018 – 2024","titulo":"«Las mates con humor entran»","detalle":"Experiencia significativa · primer lugar en la 31.ª RELME","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]},{"clave":"formacion","categoria":"formacion-docente","volanta":"Formación","color":"azul","periodo":"2004 – 2026","composicion":"ficha","titulo":"Licenciatura, maestría, doctorado y dos posdoctorados.","texto":"Se formó sin dejar la escuela: la licenciatura en la Universidad Distrital, la maestría en la Pedagógica Nacional, el doctorado en la Santo Tomás y una especialización en gerencia educativa.","cita":"","hitos":[{"periodo":"2004","titulo":"Licenciatura en Matemáticas","detalle":"Universidad Distrital Francisco José de Caldas","principal":false},{"periodo":"2010","titulo":"Magíster en Docencia de las Matemáticas","detalle":"Universidad Pedagógica Nacional","principal":false},{"periodo":"2019","titulo":"Doctora en Educación","detalle":"Universidad Santo Tomás — tesis laureada","principal":false},{"periodo":"2022","titulo":"Especialista en Gerencia Educativa","detalle":"Universidad San Buenaventura","principal":false}],"ramas":[{"periodo":"2016","lugar":"Universidad de Guadalajara","detalle":"Estancia doctoral — México"},{"periodo":"2017","lugar":"Universidad Autónoma de Chiapas","detalle":"Estancia doctoral con Gabriela Buendía"},{"periodo":"2019","lugar":"Universidad Autónoma de Chiapas","detalle":"Estancia posdoctoral en Didáctica de las Matemáticas"},{"periodo":"2026","lugar":"Universidad Distrital","detalle":"Estancia posdoctoral — mirar profesionalmente"}],"territorios":[],"publicaciones":[]},{"clave":"proporcionalidad","categoria":"pensamiento-proporcional","volanta":"La tesis laureada","color":"azul","periodo":"2019","composicion":"concepto","titulo":"Lo proporcional, estudiado en una huerta escolar.","texto":"Su doctorado estudió los usos y resignificados de la proporcionalidad en un contexto que existía de verdad: la huerta de la escuela. La tesis recibió el reconocimiento de laureada por sus aportes a la teoría socioepistemológica.","cita":"Usos y resignificados de la proporcionalidad en el contexto de la huerta escolar. Un estudio socioepistemológico.","hitos":[{"periodo":"2010","titulo":"Tesis de maestría — la modelación para resignificar la función","detalle":"","principal":false},{"periodo":"2019","titulo":"Tesis doctoral laureada — una epistemología de usos de lo proporcional","detalle":"","principal":false},{"periodo":"2026","titulo":"Investigación posdoctoral — mirar profesionalmente en la formación continua","detalle":"","principal":false}],"ramas":[],"territorios":[],"publicaciones":[{"origen":"biblioteca","material":"31d5d001-a578-42ca-8283-80183ea6b5ef","detalle":"Con Gabriela Buendía · Revista Venezolana de Investigación en Educación Matemática","conceptos":[],"destacada":true}]},{"clave":"festivales","categoria":"justicia-social","volanta":"Sacar la matemática del aula","color":"naranja","periodo":"2018 – actualidad","composicion":"hitos","titulo":"Festivales, memes y humor como recurso serio.","texto":"Creó y preside la red de festivales matemáticos de Colombia y lideró seis versiones del festival en Soacha. Su trabajo con memes y humor en el aula es también una investigación sobre qué imaginario tienen las y los estudiantes de la matemática.","cita":"","hitos":[{"periodo":"","titulo":"Creadora y presidenta de la Red de Festivales Matemáticos de Colombia","detalle":"","principal":true},{"periodo":"2024","titulo":"Festival Matemático Santanderista","detalle":"Mejor proyecto de matemáticas del municipio de Soacha","principal":false},{"periodo":"2019","titulo":"Reconocimiento «Mujeres Matemáticas»","detalle":"Sociedad Colombiana de Matemáticas","principal":false},{"periodo":"2022","titulo":"Mejor docente innovador del municipio de Soacha","detalle":"","principal":false},{"periodo":"2023","titulo":"Profesora destacada y egresada distinguida","detalle":"Universidad Pedagógica Nacional","principal":false},{"periodo":"2012","titulo":"Formadora del Programa Todos a Aprender","detalle":"Ministerio de Educación Nacional de Colombia","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]},{"clave":"universidad","categoria":"formacion-docente","volanta":"La cátedra","color":"azul","periodo":"2022 – actualidad","composicion":"hitos","titulo":"De la escuela al posgrado, sin dejar la escuela.","texto":"Da cátedra en la Universidad Pedagógica Nacional, dicta el módulo de proporcionalidad del Diplomado en Matemática Educativa de la UDLA en Chile y evalúa proyectos doctorales en varias universidades colombianas.","cita":"","hitos":[{"periodo":"","titulo":"Profesora de cátedra — Maestría en Docencia de las Matemáticas y Licenciatura en Matemáticas","detalle":"Universidad Pedagógica Nacional de Colombia","principal":true},{"periodo":"2022 – actualidad","titulo":"Módulo de proporcionalidad — Diplomado en Matemática Educativa","detalle":"Universidad De Las Américas, Santiago de Chile","principal":false},{"periodo":"2023 – 2024","titulo":"Docente asesora del Doctorado en Educación","detalle":"Universidad San Buenaventura, Cali","principal":false},{"periodo":"2025","titulo":"Evaluadora de proyectos doctorales","detalle":"U. de Antioquia · U. de La Salle · U. de Cundinamarca","principal":false},{"periodo":"","titulo":"Investigadora Junior reconocida por Minciencias","detalle":"","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]},{"clave":"produccion","categoria":"justicia-social","volanta":"Producción reciente","color":"naranja","periodo":"2025 – 2026","composicion":"ramas","titulo":"Ciudadanía, contextos y empoderamiento.","texto":"Sus publicaciones más recientes cruzan la formación ciudadana, los contextos de significación y el empoderamiento docente en la formación de posgrado, y llevan a las revistas la experiencia de