  ('a6cde7aa-bccc-4c38-bff9-44abb6387ad4', 'luis-cabrera', 'Luis Cabrera Chim', 'Facilitador · Evaluación educativa', 'México', 4, '{"src":"/equipo/luis-cabrera.jpg","alt":"Luis Cabrera Chim","foco":{"x":0.5,"y":0.15}}', false, 1.34, 4, 'Luis Manuel Cabrera Chim', 'Facilitador · Evaluación educativa', 'San Pedro Cholula, Puebla, México', NULL, 'Quince años enseñándole matemática a quienes enseñan matemática.', 'Doctor en Matemática Educativa y profesor-investigador posdoctorante en el INAOE. Diseña, coordina e imparte programas de formación docente —de talleres de actualización a posgrados— y desarrolló un esquema teórico propio para el pensamiento y lenguaje variacional.', '["Doctor en Ciencias — Matemática Educativa, Cinvestav-IPN","Profesor-Investigador Posdoctorante — INAOE","Candidato al Sistema Nacional de Investigadoras e Investigadores"]', '[{"clave":"variacional","etiqueta":"Pensamiento y lenguaje variacional","color":"verde"},{"clave":"formacion-docente","etiqueta":"Formación docente","color":"verde"},{"clave":"evaluacion","etiqueta":"Evaluación educativa","color":"naranja"},{"clave":"materiales","etiqueta":"Libros de texto y materiales","color":"azul"}]', '{"tipo":"marco","foto":{"src":"/equipo/luis-cabrera.jpg","alt":"Luis Manuel Cabrera Chim","foco":{"x":0.5,"y":0.15}},"apaisado":false}', '[{"clave":"programas","categoria":"formacion-docente","volanta":"El oficio","color":"verde","periodo":"2019 – 2022","composicion":"hitos","titulo":"De la secretaría académica al taller con docentes en servicio.","texto":"Fue Secretario Académico del Programa Interdisciplinario para el Desarrollo Profesional Docente en Matemáticas del Cinvestav-SEP y después dictó más de cien horas de talleres de actualización para profesorado en servicio de educación básica y media superior.","cita":"","hitos":[{"periodo":"2019 – 2020","titulo":"Secretario Académico — Programa Interdisciplinario para el Desarrollo Profesional Docente en Matemáticas","detalle":"Cinvestav-SEP","principal":true},{"periodo":"2021 – 2022","titulo":"Talleres de actualización para profesorado en servicio","detalle":"UASLP con la Secretaría de Educación de San Luis Potosí · más de 100 horas","principal":false},{"periodo":"2021 – 2022","titulo":"Seminarios en la Maestría en Educación","detalle":"Facultad de Psicología, UASLP","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]},{"clave":"posgrado","categoria":"formacion-docente","volanta":"El posgrado","color":"azul","periodo":"2022 – 2028","composicion":"hitos","titulo":"Profesor en tres posgrados a la vez.","texto":"Da clases en la Maestría en Enseñanza de Ciencias Exactas del INAOE, en la Especialidad en Matemática Educativa y en el Doctorado en Investigación en Aprendizaje y Docencia de la Benemérita Escuela Normal Veracruzana. También diseñó dos planes de estudio completos.","cita":"","hitos":[{"periodo":"2022 – actualidad","titulo":"Profesor-Investigador — Maestría en Enseñanza de Ciencias Exactas","detalle":"Instituto Nacional de Astrofísica, Óptica y Electrónica","principal":true},{"periodo":"2025 – 2028","titulo":"Profesor invitado — Doctorado en Investigación en Aprendizaje y Docencia","detalle":"Benemérita Escuela Normal Veracruzana","principal":false},{"periodo":"2023 – 2024","titulo":"Diseño de Situaciones de Aprendizaje — Especialidad en Matemática Educativa","detalle":"Benemérita Escuela Normal Veracruzana","principal":false},{"periodo":"","titulo":"Diseño curricular de la Maestría en Enseñanza de Ciencias Exactas y de la Licenciatura en Psicopedagogía","detalle":"INAOE y UASLP","principal":false},{"periodo":"","titulo":"Dirección de nueve tesis y sinodalías en más de veinte exámenes de grado","detalle":"","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]},{"clave":"variacional","categoria":"variacional","volanta":"Un esquema propio","color":"verde","periodo":"","composicion":"concepto","titulo":"Cómo se desarrolla el pensamiento variacional, y cómo se evalúa.","texto":"Su aporte teórico es un esquema para el desarrollo del pensamiento y lenguaje variacional: qué se pone en juego cuando alguien piensa el cambio, cómo diseñar situaciones que lo provoquen y con qué criterios evaluarlo.","cita":"","hitos":[{"periodo":"2024","titulo":"Rúbrica para evaluar el desarrollo del pensamiento y lenguaje variacional","detalle":"","principal":false},{"periodo":"2025","titulo":"Referentes teóricos para el diseño de situaciones variacionales","detalle":"","principal":false},{"periodo":"","titulo":"Más de 30 publicaciones arbitradas y más de 60 ponencias","detalle":"","principal":false}],"ramas":[],"territorios":[],"publicaciones":[{"origen":"biblioteca","material":"e30234d2-0ae3-437e-915c-3d78d4f1b806","detalle":"Capítulo — Tendencias en la Educación Matemática 2025 · Editorial SOMIDEM","conceptos":[],"destacada":true}]},{"clave":"materiales","categoria":"materiales","volanta":"Escribir para el aula","color":"azul","periodo":"2015 – 2019","composicion":"ramas","titulo":"Libros de texto de secundaria y materiales para docentes.","texto":"Es coautor de un libro de texto de matemáticas de secundaria y de su libro de recursos para el profesor, revisó técnicamente libros aprobados por la SEP y participó en la colección para docentes del Plan Nacional Aprender Matemática en Argentina.","cita":"","hitos":[],"ramas":[],"territorios":[],"publicaciones":[{"origen":"biblioteca","material":"77e32742-f657-4908-8491-ea501f0b05f0","detalle":"Coautoría de la colección para el profesor · Ministerio de Educación, Cultura, Ciencia y Tecnología de Argentina","conceptos":[],"destacada":true},{"origen":"sin-link","titulo":"Matemáticas 2, Serie espiral del saber","tipo":"Libros","anio":"2015","detalle":"Coautoría, con su Libro de Recursos para el Profesor · Editorial Santillana","conceptos":[],"destacada":false},{"origen":"biblioteca","material":"a0623e3f-213c-424f-9fe7-4984122b3b57","detalle":"Capítulo — Perspectivas actuales de la Educación Matemática · Editorial SOMIDEM","conceptos":[],"destacada":false},{"origen":"biblioteca","material":"a534cec7-b623-40da-8f4d-123f55a8ec8f","detalle":"Avances de Investigación en Educación Matemática","conceptos":[],"destacada":false},{"origen":"biblioteca","material":"a542f6bd-c0b5-4184-9cfc-caa2ea9be1fc","detalle":"","conceptos":[],"destacada":false}]},{"clave":"comunidad","categoria":"evaluacion","volanta":"La comunidad del campo","color":"naranja","periodo":"2023 – 2030","composicion":"hitos","titulo":"Presidir la red y representar a la región.","texto":"Fue elegido presidente de la Red de Centros de Investigación en Matemática Educativa y vocal por Norteamérica del Consejo Directivo del Comité Latinoamericano de Matemática Educativa.","cita":"","hitos":[{"periodo":"2026 – 2028","titulo":"Presidente de la Red de Centros de Investigación en Matemática Educativa","detalle":"","principal":true},{"periodo":"2026 – 2030","titulo":"Vocal Norteamérica — Consejo Directivo del Comité Latinoamericano de Matemática Educativa","detalle":"","principal":false},{"periodo":"2023 – 2026","titulo":"Candidato al Sistema Nacional de Investigadoras e Investigadores","detalle":"","principal":false},{"periodo":"","titulo":"Revisor de Educación Matemática, RELIME e IE-REDIECH","detalle":"","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]},{"clave":"convergencia","categoria":"evaluacion","volanta":"La convergencia","color":"verde","periodo":"actualidad","composicion":"sintesis","titulo":"Evaluación educativa en ED.","texto":"En Empoderamiento Docente facilita procesos y diseña materiales desde el desarrollo profesional docente, el pensamiento variacional y la evaluación.","cita":"","hitos":[{"periodo":"","titulo":"Facilitador y diseñador de materiales educativos — Empoderamiento Docente","detalle":"México","principal":true},{"periodo":"","titulo":"AMIUTEM · SOMIDEM · CLAME","detalle":"","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]}]', 'Un esquema teórico que termina siendo una rúbrica.', 'Investigar cómo se piensa el cambio, escribir los libros con los que se estudia y formar al profesorado que los va a usar son, en su recorrido, el mismo trabajo.', NULL, true, CURRENT_TIMESTAMP),
  ('b4c2f027-b4a2-4039-8e76-dcf0e05b3e8b', 'eduardo-briceno', 'Eduardo Briceño', 'Diseñador de material didáctico', 'México', 4, '{"src":"/equipo/eduardo-briceno.jpg","alt":"Eduardo Briceño","foco":{"x":0.5,"y":0.14}}', false, 1.3, 5, 'Eduardo Carlos Briceño Solís', 'Diseñador de material didáctico', 'Zacatecas, México', 'Yucatán, México', 'Qué aprendemos mirando cómo nuestros estudiantes usan una gráfica.', 'Doctor en Matemática Educativa y profesor-investigador titular en la Universidad Autónoma de Zacatecas. Investiga la construcción social del conocimiento matemático y el uso de la tecnología en la enseñanza, con las gráficas y el movimiento como terreno de trabajo.', '["Licenciado en Enseñanza de las Matemáticas — UADY","Maestro en Ciencias — Matemática Educativa, Cinvestav-IPN","Doctor en Ciencias — Matemática Educativa, Cinvestav-IPN"]', '[{"clave":"graficas","etiqueta":"Gráficas y modelación","color":"verde"},{"clave":"tecnologia","etiqueta":"Tecnología en la enseñanza","color":"azul"},{"clave":"desarrollo-profesional","etiqueta":"Profesionalización docente","color":"verde"}]', '{"tipo":"marco","foto":{"src":"/equipo/eduardo-briceno.jpg","alt":"Eduardo Carlos Briceño Solís","foco":{"x":0.5,"y":0.14}},"apaisado":false}', '[{"clave":"formacion","categoria":"graficas","volanta":"La formación","color":"azul","periodo":"","composicion":"ficha","titulo":"De Yucatán al Cinvestav.","texto":"Se recibió de Licenciado en Enseñanza de las Matemáticas en la Universidad Autónoma de Yucatán y obtuvo la maestría y el doctorado en Ciencias con especialidad en Matemática Educativa en el Cinvestav-IPN.","cita":"","hitos":[{"periodo":"","titulo":"Licenciatura en Enseñanza de las Matemáticas","detalle":"Universidad Autónoma de Yucatán","principal":false},{"periodo":"","titulo":"Maestría en Ciencias — Matemática Educativa","detalle":"Cinvestav-IPN","principal":false},{"periodo":"","titulo":"Doctorado en Ciencias — Matemática Educativa","detalle":"Cinvestav-IPN","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]},{"clave":"quintana-roo","categoria":"desarrollo-profesional","volanta":"El posgrado profesionalizante","color":"verde","periodo":"","composicion":"editorial","titulo":"Formar docentes que ya están dando clase.","texto":"Antes de Zacatecas fue profesor investigador en la Maestría Profesionalizante en Matemática Educativa de la Universidad de Quintana Roo: un posgrado pensado para docentes en ejercicio, no para futuros investigadores.","cita":"","hitos":[{"periodo":"","titulo":"Profesor investigador — Maestría Profesionalizante en Matemática Educativa","detalle":"Universidad de Quintana Roo","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]},{"clave":"uaz","categoria":"desarrollo-profesional","volanta":"Zacatecas","color":"verde","periodo":"2018 – actualidad","composicion":"hitos","titulo":"Profesor titular y líder de un cuerpo académico consolidado.","texto":"Es profesor-investigador de tiempo completo titular C en la Unidad Académica de Matemáticas de la Universidad Autónoma de Zacatecas y lidera el cuerpo académico consolidado «La matemática educativa en la profesionalización docente».","cita":"","hitos":[{"periodo":"2022 – actualidad","titulo":"Profesor-Investigador de tiempo completo titular C","detalle":"Unidad Académica de Matemáticas, Universidad Autónoma de Zacatecas","principal":true},{"periodo":"","titulo":"Líder del cuerpo académico consolidado UAZ-CA-243","detalle":"«La matemática educativa en la profesionalización docente»","principal":false},{"periodo":"2023","titulo":"Sistema Nacional de Investigadores, nivel 1","detalle":"","principal":false},{"periodo":"2023","titulo":"Sistema Estatal de Investigadores","detalle":"Consejo Zacatecano de Ciencia y Tecnología","principal":false},{"periodo":"2018 · 2022 · 2025","titulo":"Reconocimiento a perfil deseable","detalle":"PRODEP","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]},{"clave":"lineas","categoria":"tecnologia","volanta":"Las líneas de trabajo","color":"azul","periodo":"","composicion":"concepto","titulo":"Las gráficas no ilustran: construyen conocimiento.","texto":"Sus tres líneas se cruzan en un mismo punto: cómo se construye socialmente el conocimiento matemático cuando entran en juego el movimiento, la gráfica y la tecnología.","cita":"","hitos":[{"periodo":"","titulo":"Uso de tecnología en los procesos de enseñanza y aprendizaje de las matemáticas","detalle":"","principal":false},{"periodo":"","titulo":"Desarrollo profesional docente en matemáticas","detalle":"","principal":false},{"periodo":"","titulo":"Estudios socioculturales en educación matemática","detalle":"","principal":false}],"ramas":[],"territorios":[],"publicaciones":[{"origen":"biblioteca","material":"7e68b917-4b7f-4894-b189-4f459c89e723","detalle":"","conceptos":[],"destacada":true}]},{"clave":"produccion","categoria":"graficas","volanta":"Producción","color":"azul","periodo":"2017 – 2024","composicion":"ramas","titulo":"Del teorema de Pitágoras a la planeación de clase.","texto":"Quince artículos arbitrados, la mitad de ellos destacados. Los más recientes miran de cerca lo que hace el profesorado: qué significados pone en juego al planear y qué tecnología traen las tareas de los libros de texto.","cita":"","hitos":[],"ramas":[],"territorios":[],"publicaciones":[{"origen":"biblioteca","material":"0614b3bc-1dc7-410d-b98b-3a741c2bfb93","detalle":"Con Judith Hernández · Revista de Investigación Educativa de la REDIECH","conceptos":[],"destacada":true},{"origen":"biblioteca","material":"2e14b88e-8d13-4997-a8ca-91a558adee97","detalle":"Revista Electrónica de Investigación Educativa","conceptos":[],"destacada":false},{"origen":"biblioteca","material":"61f6e209-40bc-42f4-b6b8-b18a48830a34","detalle":"Innovación Educativa","conceptos":[],"destacada":false},{"origen":"biblioteca","material":"d4c3ba3a-5686-4a09-ab23-a485d6d39077","detalle":"","conceptos":[],"destacada":false},{"origen":"biblioteca","material":"73c41ab3-4053-4ec5-908e-c340aee1d9fb","detalle":"Con Lizbet Alamillo · Revista de Investigación Educativa de la REDIECH","conceptos":[],"destacada":false}]},{"clave":"convergencia","categoria":"graficas","volanta":"La convergencia","color":"verde","periodo":"actualidad","composicion":"sintesis","titulo":"Diseño de material didáctico en ED.","texto":"En Empoderamiento Docente diseña material didáctico desde la construcción social del conocimiento y el uso de tecnología en la enseñanza de las matemáticas.","cita":"","hitos":[{"periodo":"","titulo":"Diseñador de material didáctico — Empoderamiento Docente","detalle":"México","principal":true},{"periodo":"2020 – 2022","titulo":"Consejo directivo de la Red de Centros de Investigación en Matemática Educativa","detalle":"","principal":false}],"ramas":[],"territorios":[],"publicaciones":[]}]', 'Mirar lo que el estudiante hace, no lo que debería hacer.', 'Investigación sobre gráficas, movimiento y tecnología, un cuerpo académico consolidado y quince artículos arbitrados sostienen los materiales que diseña.', NULL, true, CURRENT_TIMESTAMP);


-- La autoría pasa de la clave de la persona (texto) al id de su fila, con la
-- fk (SPEC §4.2): se agrega la columna, se llena por el slug y recién después
-- se borra la vieja. Si una autoría tuviera una clave que no es de nadie, la
-- migración frena en vez de dejarla de afuera sin avisar.
ALTER TABLE "autorias" ADD COLUMN "persona_id" TEXT;

UPDATE "autorias" a SET "persona_id" = e."id" FROM "equipo" e WHERE e."slug" = a."persona";

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM "autorias" WHERE "persona" IS NOT NULL AND "persona_id" IS NULL) THEN
    RAISE EXCEPTION 'Hay autorías con una persona que no está en el Equipo';
  END IF;
END $$;

-- Los borradores de los materiales guardan sus autorías en el documento, con
-- la persona adentro: pasan de la clave al id igual. Una clave que no es de
-- nadie queda de afuera (nula), que es lo que el borrador puede tener.
UPDATE "materiales" m
SET "borrador" = jsonb_set(m."borrador", '{autorias}', (
  SELECT jsonb_agg(
    CASE WHEN jsonb_typeof(a->'persona') = 'string' THEN jsonb_set(a, '{persona}', COALESCE(to_jsonb(e."id"), 'null'::jsonb)) ELSE a END
    ORDER BY t.ord
  )
  FROM jsonb_array_elements(m."borrador"->'autorias') WITH ORDINALITY AS t(a, ord)
  LEFT JOIN "equipo" e ON e."slug" = t.a->>'persona'
))
WHERE jsonb_typeof(m."borrador"->'autorias') = 'array' AND jsonb_array_length(m."borrador"->'autorias') > 0;

-- DropIndex
DROP INDEX "autorias_persona_idx";

-- AlterTable
ALTER TABLE "autorias" DROP COLUMN "persona";

-- CreateIndex
CREATE INDEX "autorias_persona_id_idx" ON "autorias"("persona_id");

-- AddForeignKey
ALTER TABLE "autorias" ADD CONSTRAINT "autorias_persona_id_fkey" FOREIGN KEY ("persona_id") REFERENCES "equipo"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- Las 5 publicaciones de los perfiles que tienen link y no estaban en la
-- Biblioteca entran como materiales publicados (SPEC §5.3): los autores y la
-- cita salen de Crossref (`api.crossref.org/works/{doi}`, bajados el
-- 2026-09-27 una sola vez, al escribir esta migración), con los nombres de ED
-- como en las demás autorías; *Matemática en Red* es una página, sin DOI, y
-- lleva su firma escrita. Sin descripción (no se inventa: la escribe ED) y sin
-- portada propia: el sitio muestra la tipográfica generada. La tortilla va
-- con el año de su número (2024, el del DOI y el del perfil) y el tema que
-- dice su resumen (pensamiento variacional).
