-- Los dos títulos que la Biblioteca tenía más cortos que el perfil (SPEC §8.2,
-- precisión H del padre): su fuente (Crossref) da el entero, así que se
-- corrigen acá, en el título y en la cita. Su portada estática mostraba el
-- título corto: queda nula, y el sitio muestra la tipográfica generada con el
-- entero, igual a las demás (DECISIONS).
UPDATE "materiales"
SET "titulo" = 'Resignificación colectiva de lo cuadrático en el estudio del plano inclinado: una experiencia de modelación y tecnologías en formación inicial docente',
    "cita" = replace("cita", 'Resignificación colectiva de lo cuadrático en el estudio del plano inclinado.', 'Resignificación colectiva de lo cuadrático en el estudio del plano inclinado: una experiencia de modelación y tecnologías en formación inicial docente.'),
    "portada" = NULL
WHERE "doi" = '10.61174/recacym.v21i2.235';

UPDATE "materiales"
SET "titulo" = '¿Juguemos CATAN? Explorando el desarrollo de los pensamientos probabilístico y estratégico en estudiantes universitarios',
    "cita" = replace("cita", 'probabilístico y estratégico.', 'probabilístico y estratégico en estudiantes universitarios.'),
    "portada" = NULL
WHERE "doi" = '10.21703/rexe.v24i56.3302';
